import {
	Component,
	Element,
	Event,
	EventEmitter,
	Fragment,
	Listen,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { stopAnimations } from "../../utils/animate";
import { setDefaultAnimation } from "../../utils/animate";
import { waitForEvent } from "../../utils/browser";
import { attachElementInternals } from "../../utils/element-internals";
import {
	emitInvalidEvent,
	setValidity,
	updateValidity,
} from "../../utils/form";
import { scrollIntoView } from "../../utils/scroll";
import { hasDefaultSlot, hasSlot } from "../../utils/slot";

interface Option {
	current?: boolean;
	tabIndex?: number;
}

/**
 * @since 0.0.14
 * @status stable
 *
 * @description A select lets users select one or more items from a list.
 *
 * @slot - The listbox options. Must be `<hbr-option>` elements. You can use `<hbr-divider>` to group items visually.
 * @slot prefix - Used to prepend a presentational icon or similar element to the combobox.
 * @slot clear-icon - An icon to use in lieu of the default clear icon.
 * @slot label - The input's label. Alternatively, you can use the `label` attribute.
 * @slot label-suffix - Non-interactive content to display inline with the input label.
 * @slot label-info - Interactive informational content, such as a tooltip trigger, displayed next to the input label.
 * @slot tags - The container that houses option tags when `multiselect` is used.
 * @slot counter - The number of selected options when `multiselect` is used.
 * @slot counter-label - The label of number of selected options when `multiselect` is used.
 * @slot expand-icon - The icon to show when the control is expanded and collapsed. Rotates on open and close.
 * @slot help-text - Text that describes how to use the input. Alternatively, you can use the `help-text` attribute.
 *
 * @part base - The component's base wrapper.
 * @part clear-button - The clear button.
 * @part form-control - The form control that wraps the label, input, and help text.
 * @part label-container - The container that wraps the label and label-info slot.
 * @part label - The input label.
 * @part combobox - The container the wraps the prefix, combobox, clear icon, and expand button.
 * @part prefix -  The container that wraps the prefix slot.
 * @part counter - The number of selected options element.
 * @part display-input - The element that displays the selected option's label, an `<input>` element.
 * @part listbox - The listbox container where options are slotted.
 * @part tags - The container that houses option tags when `multiselect` is used.
 * @part tag - The individual tags that represent each multiselect option.
 * @part tag__base - The tag's base part.
 * @part tag__prefix - The tag's prefix part.
 * @part tag__content - The tag's content part.
 * @part tag__remove-button - The tag's remove button.
 * @part tag__remove-button__base - The tag's remove button base part.
 * @part clear-button - The clear button.
 * @part clear-icon - The clear button.
 * @part expand-icon - The container that wraps the expand icon.
 * @part front - Placed between label and main content in the form element.
 * @part rear - Placed after the form element before the help text.
 * @part help-text - The help text wrapper element
 *
 * @data-testid combobox - The combobox trigger element.
 * @data-testid clear-button - The clear-value button when `clearable` is enabled.
 */

/**
 * We store a Set of controls that users have interacted with. This allows us to determine the interaction state
 * without littering the DOM with additional data attributes.
 */
const userInteractedControls = new WeakSet();
/**
 * We store a WeakMap of interactions for each form control so we can track when all conditions are met for validation.
 */
const interactions = new WeakMap();

let id = 0;

@Component({
	tag: "hbr-select",
	styleUrl: "select.scss",
	shadow: true,
	formAssociated: true,
})
export class Select {
	@Element() host: HTMLHbrSelectElement;

	@State() private hasFocus = false;
	@State() displayLabel = "";
	@State() currentOption;
	@State() selectedOptions = [];
	@State() rerender = false;
	@State() private truncateContent = "";
	@State() hasLabelSlot: boolean;
	@State() hasLabelInfoSlot: boolean;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;
	@State() hasHelpTextSlot: boolean;
	@State() hasClearIconSlot: boolean;
	@State() hasExpandIconSlot: boolean;
	@State() hasTagsSlot: boolean;
	@State() hasDefaultSlot = false;
	@State() editable = false;

	private internals?: ElementInternals;

	/** The name of the select, submitted as a name/value pair with form data. */
	@Prop() name = "";

	@Prop({ mutable: true }) value: string | string[] = "";

	/** variant "multi select or tag". With this enabled, value will be an array. */
	@Prop({ reflect: true }) variant: "single" | "multiple" | "tag" = "single";

	/** The select's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** Placeholder text to show as a hint when the select is empty. */
	@Prop() placeholder = "";

	/** Allows more than one option to be selected. */
	@Prop({ reflect: true }) multiple = false;

	/** Disables the select control. */
	@Prop({ reflect: true }) disabled = false;

	/** Adds a clear button when the select is not empty. */
	@Prop({ reflect: true }) clearable = false;

	/**
	 * Indicates whether or not the select is open. You can toggle this attribute to show and hide the menu, or you can
	 * use the `show()` and `hide()` methods and this attribute will reflect the select's open state.
	 */
	@Prop({ reflect: true, mutable: true }) open = false;

	/**
	 * Enable this option to prevent the listbox from being clipped when the component is placed inside a container with
	 * `overflow: auto|scroll`. Hoisting uses a fixed positioning strategy that works in many, but not all, scenarios.
	 */
	@Prop({ reflect: true }) hoist = false;

	/** Enable the native popover feature so that the listbox layers above clipping containers. @version: 2.18.41 */
	@Prop() enablePopover = false;

	/** Draws a filled select. */
	@Prop({ reflect: true }) filled = false;

	/** Draws a pill-style select with rounded edges. */
	@Prop({ reflect: true }) pill = false;

	/** The select's label. If you need to display HTML, use the `label` slot instead. */
	@Prop() label;

	/** For SR when there is no label */
	@Prop() arialabel;

	/** @deprecated Use `<hbr-truncate>` and `<hbr-tooltip>` instead. For details, refer to the sample in the documentation. */
	@Prop() truncate: boolean;

	/** Syncs the Listbox's width or height to match the anchor element.
	 * Use "none" to prevent resizing if the anchor is smaller than the longest option's text.
	 * since v2.11.2 */
	@Prop() sync: "width" | "height" | "both" | "none" = "width";

	/**
	 * The preferred placement of the select's menu. Note that the actual placement may vary as needed to keep the listbox
	 * inside of the viewport.
	 */
	@Prop({ reflect: true, mutable: true }) placement:
		| "top"
		| "top-start"
		| "top-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "right"
		| "right-start"
		| "right-end"
		| "left"
		| "left-start"
		| "left-end";

	/** The distance in pixels from which to offset the listbox along its select anchor. */
	@Prop() skidding: number;

	/** The select's help text. If you need to display HTML, use the `help-text` slot instead. */
	@Prop({ attribute: "help-text" }) helpText = "";

	/** The select's required attribute. */
	@Prop({ reflect: true }) required = false;

	/** error state */
	@Prop({ reflect: true }) error = false;

	/**
	 * The element the popup will be anchored to. If the anchor lives outside of the popup, you can provide its `id` or a
	 * reference to it here. If the anchor lives inside the popup, use the `anchor` slot instead.
	 * @deprecated Use `enable-popover` instead to avoid external anchors and portal usage.
	 */
	@Prop() anchor: HTMLElement | string;

	/** Allow search the items(s) from the list. */
	@Prop({ mutable: true, reflect: true }) searchable: boolean;

	/** Search string */
	@Prop({ mutable: true }) search: string;

	/** Allow adding custom tags, only on variant="tag" flow. */
	@Prop() custom: boolean;

	/** Prevents users from changing the selected value while keeping its content interactive for reading. */
	@Prop({ reflect: true }) readonly = false;

	/** A text input with selectable suggestions. */
	@Prop({ reflect: true }) autocomplete = false;

	/** Set to true to control the select's state from the application / framework's side */
	@Prop({ mutable: true, reflect: true }) uncontrolled: boolean;

	/** Tooltip content if the icon button serves as a tooltip reference. */
	@Prop({ reflect: true }) tooltip: string;

	/** Indicates that the select trigger should receive focus on page load. */
	@Prop() autofocus: boolean;

	/** Allow tag wrap for multiline tag as selected value. */
	@Prop() tagWrap: boolean;

	/** Limits `variant="tag"` to a maximum number of visible tag rows before the combobox scrolls.
	 * Omit to show all tags with no max height.
	 * When setting this prop, `3` is the recommended default. @version: 2.18.35 */
	@Prop({ reflect: true }) lines?: number;

	/** The i18n (internationalization) key-value pairs. */
	@Prop() i18n: object;

	private inputId = `select-${++id}`;
	private labelId = `select-label-${id}`;
	private listboxId = `select-listbox-${id}`;
	private helpTextId = `select-help-text-${id}`;

	// private readonly hasSlotController = new HasSlotController(this, 'help-text', 'label');
	// private readonly localize = new LocalizeController(this);
	private typeToSelectString = "";
	private typeToSelectTimeout: number;
	popupEl: HTMLHbrPopupElement;
	anchorEl: HTMLHbrSelectAnchorElement;
	combobox: HTMLElement;
	private displayInput: HTMLInputElement;
	private searchInput: HTMLInputElement;
	private valueInput: HTMLInputElement;
	private listbox: HTMLElement;
	private blurTimeoutId?: number;
	private assumeInteractionOn = ["hbr-blur", "hbr-input"];
	private multiType = this.variant === "multiple" || this.variant === "tag";
	private anchorProps: object;
	private selectAnchor: HTMLElement | undefined;
	private tagLabels: string[];
	private eventTrigger: string; //listbox opens with the mouse should not trigger focus style on the option
	private selectAll: undefined | boolean | "indeterminate";
	private defaultI18n = { clearEntry: "Clear entry" };

	/** Emitted when the control's value changes. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter;

	/** Emitted when the control receives input. */
	@Event({ eventName: "hbr-input" }) hbrInput: EventEmitter;

	/** Emitted when the search input value change. */
	@Event({ eventName: "hbr-search" }) hbrSearch: EventEmitter;

	/** Emitted when the control gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	/** Emitted when the control loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	/** Emitted when the control's value is cleared. */
	@Event({ eventName: "hbr-clear" }) hbrClear: EventEmitter;

	/** Emitted when the select's menu opens. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted when the select's menu closes. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the select's menu opens and all animations are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted after the select's menu closes and all animations are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	/** Emitted when the combobox receives input  */
	@Event({ eventName: "hbr-combo-input" }) hbrComboInput: EventEmitter;

	/** Emitted when the form control has been checked for validity and its constraints aren't satisfied. */
	@Event({ eventName: "hbr-invalid" }) hbrInvalid: EventEmitter;

	/** Gets the validity state object */
	get validity() {
		return this.valueInput?.validity;
	}

	/** Gets the validation message */
	get validationMessage() {
		return this.valueInput?.validationMessage;
	}

	connectedCallback() {
		this.internals ??= attachElementInternals(this.host);
		// Because this is a form control, it shouldn't be opened initially
		this.open = false;

		// Listen for interactions
		interactions.set(this.host, []);
		this.assumeInteractionOn.forEach((event) => {
			this.host.addEventListener(event, this.handleInteraction);
		});

		this.handleDefaultSlotChange = this.handleDefaultSlotChange.bind(this);
		this.handleInvalid = this.handleInvalid.bind(this);
		this.handleBlur = this.handleBlur.bind(this);
		this.handleSearch = this.handleSearch.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleClearClick = this.handleClearClick.bind(this);
		this.handleDisabledChange = this.handleDisabledChange.bind(this);
		this.handleComboboxKeyDown = this.handleComboboxKeyDown.bind(this);
		this.handleComboboxMouseDown = this.handleComboboxMouseDown.bind(this);
		this.handleOptionClick = this.handleOptionClick.bind(this);
		this.handleTagRemove = this.handleTagRemove.bind(this);
		this.handlePopupHide = this.handlePopupHide.bind(this);
		this.handlePopupKeydown = this.handlePopupKeydown.bind(this);
		if (!this.placement) {
			/** moving the default value here from Prop so we can conditionally set if sync is none or not */
			this.placement = this.sync === "none" ? "bottom-start" : "bottom";
		}
	}

	componentWillLoad() {
		if (this.autocomplete) {
			this.searchable = true;
		}
		if (this.searchable) {
			this.uncontrolled = true;
		}
		this.hasDefaultSlot = hasDefaultSlot(this.host);
		this.eventTrigger = undefined;

		//angular doesn't run watch("variant") on initial render
		if (
			!this.multiType &&
			(this.variant === "multiple" || this.variant === "tag")
		) {
			this.multiType = true;
		}
		// secure the tagLabels and selectedOptions if value is not empty
		if (this.searchable && this.value?.length) {
			if (
				!this.selectedOptions?.length ||
				(this.variant === "tag" && !this.tagLabels?.length)
			) {
				this.handleValueChange();
			}
		}
	}
	componentDidLoad() {
		/** double check */
		if (this.selectAll === undefined) {
			this.setSelectAll();
		}
	}

	componentWillUpdate() {
		/** When the client-side updates trigger re-renders, the classes on the host are removed.
		 * Therefore, we need to reapply them.
		 */
		if (this.selectAll !== undefined) {
			if (!this.host.classList.contains("hbr-select-checkbox")) {
				this.host.classList.add("hbr-select-checkbox");
			}
			/** need for divider style */
			if (!this.host.classList.contains("hbr-select-all")) {
				this.host.classList.add("hbr-select-all");
			}
		}
	}

	componentWillRender() {
		if (this.variant === "tag") {
			if (this.selectedOptions?.length) {
				// For the custom style of flex start
				this.host.classList.add("select-tag--selected");
			} else {
				this.host.classList.remove("select-tag--selected");
			}
		}
		this.hasLabelSlot = hasSlot(this.host, "label");
		this.hasLabelInfoSlot = hasSlot(this.host, "label-info");
		this.hasClearIconSlot = hasSlot(this.host, "clear-icon");
		this.hasExpandIconSlot = hasSlot(this.host, "expand-icon");
		this.hasTagsSlot = hasSlot(this.host, "tags");
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");

		const hasCounterSlot = hasSlot(this.host, "counter");
		const hasLabel = this.label ? true : !!this.hasLabelSlot;
		const hasHelpText = this.helpText ? true : !!this.hasHelpTextSlot;
		if (this.open && hasHelpText) {
			const helpText = this.anchorEl?.shadowRoot.querySelector(
				".form-control__help-text",
			);
			helpText?.classList.add("select__hide-helpText");
		}
		if (this.open && this.hasRearSlot) {
			const rear = this.anchorEl?.shadowRoot.querySelector(
				".form-control__rear",
			);
			rear?.classList.add("select__hide-rear");
		}
		const optionSlotsExist =
			this.autocomplete || (!this.autocomplete && this.getAllOptions().length);

		const showClearIcon =
			(this.clearable && this.editable && this.displayInput?.value) ||
			this.value?.length > 0;

		const hasClearIcon = !!(
			this.clearable &&
			!this.disabled &&
			!this.readonly &&
			showClearIcon &&
			optionSlotsExist
		);

		const isPlaceholderVisible = !!(
			this.placeholder && this.value?.length === 0
		);
		const showPrefix = !!(this.variant === "single" || !this.value?.length);
		const hideInput = !!(
			(this.variant === "tag" ||
				(!this.searchable && this.variant === "multiple")) &&
			this.value?.length
		); //searchable need input for the search
		const cssClasses = {
			select: true,
			"select--open": this.open,
			"select--empty": this.value?.length === 0,
			"select--clearable": this.clearable,
			"select--focused": this.hasFocus,
			"select--disabled": this.disabled,
			"select--readonly": this.readonly,
			"select--multiType": this.multiType,
			"select--single": this.variant === "single",
			"select--multi": this.variant === "multiple",
			"select--tag": this.variant === "tag",
			"select--searchable": this.searchable,
			"select--standard": true,
			"select--filled": this.filled,
			"select--placeholder-visible": isPlaceholderVisible,

			"select--has-num": this.variant === "multiple" && 0 < this.value?.length,
			"select--has-tags": this.variant === "tag" && 0 < this.value?.length,
			"select--small": this.size === "small",
			"select--medium": this.size === "medium",
			"select--large": this.size === "large",
			"select--pill": this.pill,
			"select--error": this.error,
			"select--top": this.placement === "top",
			"select--bottom": this.placement === "bottom",
			"select--autocomplete": this.autocomplete,
			"select--all": this.variant !== "single" && this.selectAll !== undefined,
			"select--uncontrolled": this.uncontrolled,
		};

		this.anchorProps = {
			inputId: this.inputId,
			label: this.label,
			labelId: this.labelId,
			arialabel: this.arialabel,
			listboxId: this.listboxId,
			hasLabel: hasLabel,
			hasLabelSlot: this.hasLabelSlot,
			hasLabelInfoSlot: this.hasLabelInfoSlot,
			hasFrontSlot: this.hasFrontSlot,
			hasRearSlot: this.hasRearSlot,
			hasCounterSlot: hasCounterSlot,
			hasClearIcon: hasClearIcon,
			showPrefix: showPrefix,
			hideInput: hideInput,
			helpTextId: this.helpText ? this.helpTextId : undefined,
			helpText: this.helpText,
			hasHelpText: hasHelpText,
			hasHelpTextSlot: this.hasHelpTextSlot,
			size: this.size,
			variant: this.variant,
			placeholder: this.placeholder,
			value: this.value,
			displayLabel: this.displayLabel,
			disabled: this.disabled,
			required: this.required,
			error: this.error,
			open: this.open,
			selectedOptions: this.selectedOptions,
			setDisplayInputRef: this.setDisplayInputRef.bind(this),
			setSearchInputRef: this.setSearchInputRef.bind(this),
			setComboboxRef: this.setComboboxRef.bind(this),
			setValueInputRef: this.setValueInputRef.bind(this),
			handleLabelClick: this.handleLabelClick,
			handleFocus: this.handleFocus.bind(this),
			handleKeyUp: this.handleKeyUp.bind(this),
			handleBlur: this.handleBlur.bind(this),
			handleSearch: this.handleSearch.bind(this),
			handleComboboxKeyDown: this.handleComboboxKeyDown,
			handleComboboxMouseDown: this.handleComboboxMouseDown,
			handleInvalid: this.handleInvalid,
			handleClearMouseDown: this.handleClearMouseDown,
			handleClearClick: this.handleClearClick,
			handleTagRemove: this.handleTagRemove,
			toggleOptionSelection: this.toggleOptionSelection,
			focusFunc: this.focusFunc,
			pill: this.pill,
			cssClasses,
			searchable: this.searchable,
			custom: this.custom,
			readonly: this.readonly,
			tooltip: this.tooltip,
			autocomplete: this.autocomplete,
			autofocus: this.autofocus,
			uncontrolled: this.uncontrolled,
			search: this.search,
			editable: this.editable,
			tagWrap: this.variant === "tag" && this.tagWrap,
			lines: this.variant === "tag" ? this.lines : undefined,
			tagLabels: this.tagLabels,
			i18n: { ...this.defaultI18n, ...this.i18n },
			eventTrigger: this.eventTrigger,
			truncate: this.truncate,
			displayInput: this.displayInput,
		};

		this.syncExternalAnchor();
	}

	disconnectedCallback() {
		this.teardownExternalAnchor();
		this.truncateContent = "";
		this.clearPendingBlurCheck();
		// Clean up interactions
		interactions.delete(this.host);
		this.assumeInteractionOn.forEach((event) => {
			this.host.removeEventListener(event, this.handleInteraction);
		});
		this.eventTrigger = undefined;
	}

	private handleTruncate = (
		event: CustomEvent<{ truncated: boolean; content: string }>,
	) => {
		const { truncated, content } = event.detail;
		this.truncateContent = truncated ? content : "";
	};

	private getExternalAnchor() {
		if (!this.anchor) {
			return undefined;
		}

		if (typeof this.anchor === "string") {
			return document.querySelector(this.anchor) as HTMLElement;
		}

		if (this.anchor instanceof HTMLElement) {
			return this.anchor;
		}

		return undefined;
	}

	private teardownExternalAnchor() {
		if (!this.selectAnchor) {
			return;
		}

		this.selectAnchor.removeEventListener(
			"hbr-truncate",
			this.handleTruncate as EventListener,
		);
		this.selectAnchor = undefined;
		this.truncateContent = "";
	}

	private syncExternalAnchor() {
		// Most instances don't use an external anchor — skip all work early
		if (!this.anchor) {
			if (this.selectAnchor) {
				this.teardownExternalAnchor();
			}
			return;
		}

		const externalAnchor = this.getExternalAnchor();

		if (this.selectAnchor && this.selectAnchor !== externalAnchor) {
			this.teardownExternalAnchor();
		}

		if (!externalAnchor) {
			if (this.truncateContent) {
				this.truncateContent = "";
			}
			return;
		}

		if (this.selectAnchor !== externalAnchor) {
			this.selectAnchor = externalAnchor;
			this.selectAnchor.addEventListener(
				"hbr-truncate",
				this.handleTruncate as EventListener,
			);
		}

		Object.assign(externalAnchor, this.anchorProps);
	}

	private getTooltipAnchor() {
		return this.displayInput || this.getExternalAnchor();
	}

	private handleInteraction = (event: Event) => {
		const emittedEvents = interactions.get(this.host) ?? undefined;

		if (!emittedEvents.includes(event.type)) {
			emittedEvents.push(event.type);
		}

		// Mark it as user-interacted as soon as all associated events have been emitted
		if (emittedEvents.length === this.assumeInteractionOn.length) {
			this.setUserInteracted(this.host, true);
		}
	};
	private setUserInteracted(el, hasInteracted: boolean) {
		if (hasInteracted) {
			userInteractedControls.add(el);
		} else {
			userInteractedControls.delete(el);
		}
		/*** force to run again. */
		this.rerender = !this.rerender;
	}

	private clearPendingBlurCheck() {
		if (this.blurTimeoutId) {
			window.clearTimeout(this.blurTimeoutId);
			this.blurTimeoutId = undefined;
		}
	}

	private isFocusWithinSelect(activeElement: Element | null) {
		if (!activeElement) {
			return false;
		}

		if (activeElement === this.host || this.host.contains(activeElement)) {
			return true;
		}

		const externalAnchor = this.getExternalAnchor();
		if (
			externalAnchor &&
			(activeElement === externalAnchor ||
				externalAnchor.contains(activeElement))
		) {
			return true;
		}

		return false;
	}

	private addOpenListeners() {
		document.addEventListener("focusin", this.handleDocumentFocusIn);
		document.addEventListener("keydown", this.handleDocumentKeyDown);
		document.addEventListener("mousedown", this.handleDocumentMouseDown);
	}

	private removeOpenListeners() {
		document.removeEventListener("focusin", this.handleDocumentFocusIn);
		document.removeEventListener("keydown", this.handleDocumentKeyDown);
		document.removeEventListener("mousedown", this.handleDocumentMouseDown);
	}

	private handleFocus() {
		this.clearPendingBlurCheck();
		this.hasFocus = true;
		if (!this.searchable) {
			if (this.displayInput?.tagName === "INPUT") {
				//input only
				this.displayInput?.setSelectionRange(0, 0); //sets the start and end positions of the current text selection
			}
		}
		this.hbrFocus.emit();
	}

	private handleKeyUp(event: KeyboardEvent) {
		if (this.searchable) {
			event.preventDefault();
			event.stopPropagation();
			/** KB focus */
			this.combobox?.classList.add("keyboard--focused");

			const { key, target } = event;
			this.eventTrigger = event.key;
			if (this.editable) {
				if (key === "Escape" || key === "Esc") {
					this.open = false;
				}
				return;
			}
			if (target === this.displayInput && (key === "Tab" || key === "Enter")) {
				this.editable = true;
			}
		}
	}

	private handleBlur() {
		this.hasFocus = false;
		this.combobox?.classList.remove("keyboard--focused");
		this.clearPendingBlurCheck();

		// Use a focusin listener to detect if focus returns to the select
		const onFocusIn = (event: FocusEvent) => {
			if (this.isFocusWithinSelect(event.target as Element)) {
				this.clearPendingBlurCheck();
			}
		};

		document.addEventListener("focusin", onFocusIn, { once: true });

		this.blurTimeoutId = window.setTimeout(() => {
			this.blurTimeoutId = undefined;
			document.removeEventListener("focusin", onFocusIn);
			if (this.isFocusWithinSelect(document.activeElement)) {
				return;
			}
			this.setUserInteracted(this.host, true);
			this.hbrBlur.emit();
		});
		if (this.editable && this.variant !== "tag") {
			//causing race condition issue on searchable tag
			setTimeout(() => {
				this.editable = false;
			}, 100);
		}
	}

	private handleSearch(event) {
		if (this.searchable) {
			const { value } = event.target;
			this.hbrSearch.emit({ value });
		}
	}

	private handleDocumentFocusIn = (event: KeyboardEvent) => {
		// Close when focusing out of the select
		const path = event.composedPath();
		if (this && !path.includes(this.host)) {
			if (
				!this.anchor ||
				!path.some((el: Element) => el.localName === "hbr-select-anchor")
			) {
				this.hide();
			}
		}
	};

	private handleDocumentKeyDown = async (event: KeyboardEvent) => {
		if (this.readonly) {
			return;
		}

		const target = event.target as HTMLElement;
		const isSpaceKey = event.key === " " || event.code === "Space";
		const isClearButton = target.closest(".select__clear") !== null;
		const isIconButton = target.closest("hbr-icon-button") !== null;
		const isOption = target.closest("hbr-option") !== null;
		this.eventTrigger = event.key || "mouse";

		// Ignore if it's add new option flow
		if (target.classList.contains("hbr-event__allow-default-behavior")) {
			return;
		}

		// Ignore presses when the target is an icon button (e.g. the remove button in <hbr-tag>)
		if (isClearButton || isIconButton) {
			return;
		}
		/** new option add button is in disaplay and a Tab pressed, focus should move to the add button */
		const focusOnAddButton =
			this.editable &&
			this.variant === "single" &&
			this.open &&
			event.key === "Tab";
		if (focusOnAddButton) {
			const addOption =
				this.host.querySelector<HTMLHbrOptionElement>("hbr-option[custom]");
			if (addOption && !addOption.disabled) {
				addOption.focus();
				return;
			}
		}

		if (this.searchable && this.open && isSpaceKey && !isOption) {
			return;
		}

		// Handle enter and space. When pressing space, we allow for type to select behaviors so if there's anything in the
		// buffer we _don't_ close it.
		if (
			!this.editable &&
			(event.key === "Enter" || (isSpaceKey && this.typeToSelectString === ""))
		) {
			event.preventDefault();
			event.stopImmediatePropagation();

			// If it's not open, open it
			if (!this.open) {
				this.eventTrigger = event.key || "mouse";
				this.show();
				return;
			}

			// If it is open, update the value based on the current selection and close it
			/** adding !this.currentOption.custom condition due to adding new option flow. if entered new option and press enter key it works as expected.
			 * however press arrow down to select the new option div. then tab to '+Add' button it sets value "new option" in single select however it doesn't add 'selected' on the option.
			 * it's caused by setting currentOption on arrowDown to select the new option div */
			if (
				this.currentOption &&
				!this.currentOption.custom &&
				!this.currentOption.disabled
			) {
				if (this.multiType) {
					/** select all use case */
					if (
						this.selectAll !== undefined &&
						this.currentOption.dataset.check === "all"
					) {
						if (this.variant === "single" || this.disabled) {
							return; /** only valid with multiple counter / tags. */
						}
						const checkbox = this.currentOption.querySelector("hbr-checkbox");
						if (checkbox) {
							this.hbrChange.emit({
								option: this.currentOption,
								selectAll: true,
							});
						}

						return;
					}

					this.toggleOptionSelection(this.currentOption);
				} else {
					this.setSelectedOptions(this.currentOption);
				}

				// Emit after updating
				setTimeout(() => {
					this.hbrInput.emit();
					this.hbrChange.emit({ option: this.currentOption });
				});

				if (!this.multiType) {
					this.hide();
					this.displayInput?.focus({ preventScroll: true });
				}
			} else if (
				this.variant === "single" &&
				(event.target as HTMLElement)?.closest("hbr-option")
			) {
				this.hide();
				this.displayInput?.focus({ preventScroll: true });
			}
			return;
		}

		if (
			this.editable &&
			(event.key === "Enter" || (isSpaceKey && this.typeToSelectString === ""))
		) {
			if ((event.target as HTMLElement).closest("hbr-option")) {
				//shouldn't click option unless focus is on the option
				this.handleOptionClick(event);
			} else {
				const targetValue = (event.target as HTMLInputElement).value;
				if (!targetValue?.length) {
					//only empty string. otherwise, space bar doesn't work for typing space
					event.preventDefault();
				}
				this.open = false;
				this.hbrInvalid.emit({
					value: this.displayInput?.value,
				});
			}
			setTimeout(() => {
				// should focus the input after the click
				this.editable = true;
			});
		}

		// Navigate options
		if (["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) {
			this.eventTrigger = event.key;
			const allOptions = this.getAllOptions();
			const currentIndex = allOptions.indexOf(this.currentOption);
			let newIndex = Math.max(0, currentIndex);

			// Prevent scrolling
			event.preventDefault();

			// Open it
			if (!this.open) {
				this.show();
				if (this.searchable) {
					this.editable = true;
				}

				// If an option is already selected, stop here because we want that one to remain highlighted when the listbox
				// opens for the first time
				if (this.currentOption) {
					return;
				}
			}

			if (event.key === "ArrowDown") {
				newIndex = currentIndex + 1;

				/** skip focus on disabled item */
				if (allOptions[newIndex]?.disabled) {
					while (allOptions[newIndex]?.disabled) {
						newIndex++;
					}
				}
				if (newIndex > allOptions.length - 1) newIndex = 0;
			} else if (event.key === "ArrowUp") {
				newIndex = currentIndex - 1;

				if (newIndex < 0) newIndex = allOptions.length - 1;

				/** skip focus on disabled item */
				if (allOptions[newIndex]?.disabled) {
					while (allOptions[newIndex]?.disabled) {
						newIndex--;
					}
				}
			} else if (event.key === "Home") {
				newIndex = 0;
			} else if (event.key === "End") {
				newIndex = allOptions.length - 1;
			}
			this.setCurrentOption(allOptions[newIndex]); // focus new option div as well
		}

		if (!this.searchable) {
			// All other "printable" keys trigger type to select
			if (event.key.length === 1 || event.key === "Backspace") {
				const allOptions = this.getAllOptions();

				// Don't block important key combos like CMD+R
				if (event.metaKey || event.ctrlKey || event.altKey) {
					return;
				}

				// Open, unless the key that triggered is backspace
				if (!this.open) {
					if (event.key === "Backspace") {
						return;
					}
					this.show();
				}

				event.stopPropagation();
				event.preventDefault();

				this.typeToSelectString = "";
				clearTimeout(this.typeToSelectTimeout);
				this.typeToSelectTimeout = window.setTimeout(() => {}, 1000);

				if (event.key === "Backspace") {
					this.typeToSelectString = this.typeToSelectString.slice(0, -1);
				} else {
					this.typeToSelectString += event.key.toLowerCase();
				}

				for (const option of allOptions) {
					/** if option.display exists, show it first */
					const textContent = this.getTextContent(option);
					const label = option.display
						? option.display.toLowerCase()
						: textContent || (await option.getTextLabel())?.toLowerCase();

					if (label.startsWith(this.typeToSelectString)) {
						this.setCurrentOption(option);
						break;
					}
				}
			}
		}
	};

	private handleDocumentMouseDown = (event: MouseEvent) => {
		this.eventTrigger = "mouse";
		// Close when clicking outside of the select
		const path = event.composedPath();
		if (this && !path.includes(this.host)) {
			if (
				!this.anchor ||
				!path.some((el: Element) => el.localName === "hbr-select-anchor")
			) {
				this.hide();
			}
		}
	};

	private handleLabelClick() {
		this.displayInput?.focus();
	}

	private handleComboboxMouseDown(event: MouseEvent) {
		const path = event.composedPath();
		const isIconButton = path.some(
			(el: Element) => el.tagName?.toLowerCase() === "hbr-icon-button",
		);

		// Ignore disabled controls and clicks on tags (remove buttons)
		if (this.disabled || this.readonly || isIconButton) {
			return;
		}

		// For autocomplete, when the click lands inside the input area (either the
		// editable search input or the readonly display input), preserve native
		// cursor placement and text selection by NOT calling preventDefault. The
		// listbox should only open when the input already has a value so we don't
		// obscure the field while the user is placing their cursor.
		const isAutocompleteInputClick =
			this.autocomplete &&
			((!!this.searchInput && path.includes(this.searchInput)) ||
				(!!this.displayInput && path.includes(this.displayInput)));

		if (isAutocompleteInputClick) {
			this.eventTrigger = "mouse";
			const wasEditable = this.editable;
			if (this.uncontrolled) {
				this.editable = true;
			}
			// Only open the listbox if the user was already actively searching
			// (already in edit mode with typed text) AND there are options to show.
			// A fresh click that transitions from the display input to the search
			// input — e.g. after selecting an option — should not reopen the
			// listbox, and we should never open an empty listbox.
			if (
				wasEditable &&
				this.searchInput?.value &&
				this.getAllOptions().length > 0
			) {
				this.open = true;
			}
			return;
		}

		event.preventDefault();
		this.displayInput?.focus({ preventScroll: true });
		this.eventTrigger = "mouse"; //do not add focus style on mouse click

		if (this.hasDefaultSlot) {
			if (
				!this.multiType ||
				(event.currentTarget as HTMLDivElement)?.classList.contains(
					"select__combobox",
				)
			) {
				this.open = !this.open;
			} else {
				//make sure don't close on option click
				this.open = true;
			}
		} else {
			this.open = false;
		}

		if (this.uncontrolled) {
			this.editable = true;
		}
	}

	private handleComboboxKeyDown(event: KeyboardEvent) {
		event.stopPropagation();
		this.handleDocumentKeyDown(event);
	}

	private handleClearClick(event: MouseEvent) {
		event.stopPropagation();
		if (this.readonly) {
			return;
		}

		if (this.value !== "") {
			if (!this.uncontrolled) {
				this.setSelectedOptions([]);
				this.value = ""; // Reset the value, otherwise it will be set back on #753.
				this.displayInput?.focus({ preventScroll: true });
				// Emit after update
				setTimeout(() => {
					this.hbrClear.emit();
					this.hbrInput.emit();
					this.hbrChange.emit();
				});
			} else {
				setTimeout(() => {
					this.hbrClear.emit();
					this.displayLabel = "";
					if (this.displayInput) {
						this.displayInput.focus({ preventScroll: true });
						this.displayInput.value = this.displayLabel;
					}
				});
			}
		}
	}

	private handleClearMouseDown(event: MouseEvent) {
		// Don't lose focus or propagate events when clicking the clear button
		event.stopPropagation();
		event.preventDefault();
	}

	private handleOptionClick(event: MouseEvent | KeyboardEvent) {
		if (this.readonly) {
			return;
		}

		const target = event.target as HTMLElement;
		const option = target.closest("hbr-option");

		const oldValue = this.value;
		if (option) {
			if (!option.disabled) {
				if (option?.dataset?.check === "all") {
					if (this.variant === "single" || this.disabled) {
						return; /** only valid with multiple counter / tags. */
					}
					if (this.multiType) {
						option.selected = !option.selected;
					}
					this.hbrChange.emit({
						option,
						selectAll: true,
					});
					return;
				}
				if (option.custom) {
					this.editable = false;
					if (!this.multiType) {
						this.open = false;
					}
					return;
				}
				if (this.multiType) {
					this.toggleOptionSelection(option);
				} else {
					this.setSelectedOptions(option);
				}
				if (this.uncontrolled && this.editable) {
					setTimeout(() => {
						this.editable = false;
					}, 100);
				}

				// Set focus after updating so the value is announced by screen readers
				setTimeout(() => this.displayInput?.focus({ preventScroll: true }));

				if (this.uncontrolled || this.value !== oldValue) {
					// Emit after updating
					setTimeout(() => {
						this.hbrInput.emit();
						this.hbrChange.emit({ option });
					});
				}

				if (!this.multiType) {
					this.hide();
					setTimeout(() => this.displayInput?.focus({ preventScroll: true }));
				}
			}
		} else if (this.searchable) {
			/** should not close when click on the scroll bar */
			if (target.classList.contains("select__listbox")) {
				return;
			}

			/** adding new custom option ux as if existing option click */
			this.editable = false;
			if (!this.multiType) {
				this.open = false;
			}
		}
	}

	private setSelectAll() {
		if (this.host.classList.contains("hbr-select-checkbox")) {
			return; /** already set */
		}
		if (this.disabled || this.variant === "single") {
			return; /** only valid with multiple counter / tags. */
		}

		const firstOption = this.getFirstOption();
		if (!firstOption) {
			return;
		}

		const checkbox = firstOption.querySelector("hbr-checkbox");
		if (!checkbox) {
			return;
		}

		this.host.classList.add("hbr-select-checkbox");

		if (this.host.classList.contains("hbr-select-all")) {
			return; /** already set */
		}

		const dataCheck = firstOption.dataset?.check;
		if (!dataCheck || dataCheck !== "all") {
			return;
		}

		if (checkbox.querySelector("hbr-icon[slot]")) {
			return; /** no icon allowed */
		}

		this.selectAll = checkbox.indeterminate
			? "indeterminate"
			: checkbox.checked;

		this.host.classList.add("hbr-select-all");
	}

	private handleDefaultSlotChange() {
		this.hasDefaultSlot = hasDefaultSlot(this.host);
		if (!this.hasDefaultSlot) {
			this.open = false;
			return;
		}
		const allOptions = this.getAllOptions();
		if (this.uncontrolled) {
			if (this.editable && !this.open && this.host.children?.length) {
				this.open = true;
			}
		}

		let value: string | string[];
		if (this.multiType && this.value?.length && !Array.isArray(this.value)) {
			//sanity check
			value = this.value?.split(",");
		} else {
			value = Array.isArray(this.value) ? this.value : [this.value];
		}

		const values: string[] = [];

		// Check for duplicate values in menu items
		if (customElements.get("hbr-option")) {
			allOptions.forEach((option) => {
				if (this.truncate) {
					option.truncate = true;
				}
				return values.push(option.value);
			});

			// Select only the options that match the new value
			if (this.multiType && this.editable) {
				allOptions.forEach((option) => {
					option.selected = false;
				});
				return;
			}
			this.setSelectedOptions(
				allOptions.filter((el) => value.includes(el.value)),
			);
		} else {
			// Rerun this handler when <hbr-option> is registered
			customElements
				.whenDefined("hbr-option")
				.then(() => this.handleDefaultSlotChange());
		}

		/** Select all */
		this.setSelectAll();
	}

	private handleTagRemove(option, event) {
		event.stopPropagation();

		if (!this.disabled && !this.readonly) {
			this.toggleOptionSelection(option, false);

			// Emit after updating
			setTimeout(() => {
				this.hbrInput.emit();
				this.hbrChange.emit({ option });
				this.displayInput?.focus();
			});
		}
	}

	private handlePopupHide(event) {
		// for external anchor use case.
		// https://github.com/cisco-harbor/elements/issues/1170

		event.stopPropagation();
		if (this.open) {
			this.open = false;
			if (event?.detail?.type === "escape") {
				if (this.uncontrolled) {
					//make sure to focus the input on escape key pressed if searchable or autocomplete
					setTimeout(() => this.displayInput?.focus(), 100);
				}
			}
		}
	}

	private handlePopupKeydown(event: KeyboardEvent) {
		const { key } = event;
		if (key === "Escape" || key === "Esc") {
			event.preventDefault();
			event.stopPropagation();
			this.displayInput?.focus({ preventScroll: true });
		}
	}

	// Gets an array of all <hbr-option> elements
	private getAllOptions() {
		return [...this.host.querySelectorAll("hbr-option")];
	}

	// Gets the first <hbr-option> element
	private getFirstOption() {
		return this.host.querySelector("hbr-option");
	}

	// Sets the current option, which is the option the user is currently interacting with (e.g. via keyboard). Only one
	// option may be "current" at a time.
	private setCurrentOption(option) {
		const allOptions = this.getAllOptions();

		// Clear selection
		allOptions.forEach((el: Option) => {
			el.current = false;
			el.tabIndex = -1;
		});

		// Select the target option
		if (option) {
			this.currentOption = option;

			option.current = true;
			option.tabIndex = option.disabled ? -1 : 0;
			// focus style should be only with keyboard event
			if (this.eventTrigger !== "mouse" && !option.disabled) {
				option.focus();
			}
		}
	}

	// Sets the selected option(s)
	private setSelectedOptions(option) {
		const allOptions = this.getAllOptions();
		const newSelectedOptions = Array.isArray(option) ? option : [option];

		// Clear existing selection
		// biome-ignore lint/suspicious/noAssignInExpressions: <explanation>
		allOptions.forEach((el) => (el.selected = false));

		// Set the new selection
		if (newSelectedOptions.length) {
			newSelectedOptions.forEach((el) => {
				el.selected = true;
			});
		}

		if (this.uncontrolled) {
			// React app renders twice and on the second render it picks up this.displayLabel
			// however angular app doesn't render twice so we need to set the displayLabel to ensure it displays as expected
			if (this.variant === "single" && this.value && !this.displayLabel) {
				const allOptions = this.getAllOptions();
				if (allOptions.length) {
					const selected = allOptions.find((el) => el.value === this.value);
					if (selected) {
						this.displayLabel = selected.textContent;
					}
				}
			}
			return;
		}

		// Update selection, value, and display label
		this.selectionChanged(option);
	}

	// Toggles an option's selected state
	private toggleOptionSelection(option, force?: boolean) {
		if (force === true || force === false) {
			option.selected = force;
		} else {
			option.selected = !option.selected;
		}
		if (this.uncontrolled) {
			return;
		}
		this.selectionChanged(option);
	}

	// This method must be called whenever the selection changes. It will update the selected options cache, the current
	// value, and the display value
	private async selectionChanged(option?: HTMLHbrOptionElement) {
		if (this.uncontrolled && option && option.custom) {
			// add this custom option ot the value list?
			return;
		}
		// Update selected options cache
		const allOptions = this.getAllOptions();
		this.selectedOptions = allOptions.filter((el) => el.selected);

		// Update the value and display label
		if (this.multiType) {
			// const CustomOptionSelected = option?.custom;

			const selectedOptionsArray = this.selectedOptions.map((el) => el.value);

			/** if data changes dynamically like reset to empty, we need to clear off the displayLabel. */
			const clearOffLabel =
				this.displayLabel !== "" && this.value?.length === 0;

			if (JSON.stringify(this.value) === JSON.stringify(selectedOptionsArray)) {
				if (clearOffLabel) {
					this.displayLabel = "";
				}
				return;
			}
			if (this.editable) {
				if (clearOffLabel) {
					this.displayLabel = "";
				}
				return;
			}
			this.value = selectedOptionsArray;

			if (this.placeholder && this.value?.length === 0) {
				// When no items are selected, keep the value empty so the placeholder shows
				this.displayLabel = "";
			} else {
				if (!this.placeholder && this.value?.length === 0) {
					/** Ensure that an empty input label is displayed when neither a value nor a placeholder is set." */
					this.displayLabel = "";
				} else {
					this.displayLabel = `${this.selectedOptions.length} ${
						this.value?.length === 1 ? "option" : "options"
					} selected`;
				}
			}

			/** To-Do for custom prop */
			// if (CustomOptionSelected && this.value.length) {
			// 	this.hbrChange.emit({
			// 		option: [...this.value, ...selectedOptionsArray],
			// 	});
			// 	this.displayLabel = "";
			// 	if (this.displayInput) {
			// 		this.displayInput.value = this.displayLabel;
			// 	}
			// } else {
			// 	const { length } = allOptions;
			// 	const customOption = this.multiType && length === 1;
			// 	const optionFromSearchResult =
			// 		1 < length && allOptions[length - 1].custom;
			// 	// selected options are not in the slot since slot changed based on the search
			// 	if (customOption || optionFromSearchResult) {
			// 		this.displayLabel = "";
			// 		if (this.displayInput) {
			// 			this.displayInput.value = this.displayLabel;
			// 		}
			// 	}
			// 	this.hbrChange.emit({
			// 		option: optionFromSearchResult
			// 			? [...this.value, ...selectedOptionsArray]
			// 			: selectedOptionsArray,
			// 	});
			// }
		} else {
			/**
       * When a value is set with empty options, the value gets reset to and empty string.
       This behavior is causing an issue on Angular application side which options are loaded, the value is preserved as empty string
       instead of previous set.
       */
			const selectedOption = this.selectedOptions[0];
			this.value = selectedOption?.value ?? this.value;
			if (this.searchable) {
				//uncontrolled
				return;
			}

			if (this.autocomplete && this.value && !selectedOption) {
				this.displayLabel = Array.isArray(this.value)
					? this.value[0]
					: this.value; // Assign the first value of this.value
			} else {
				const textContent = this.getTextContent(selectedOption);
				/** Make sure to honor the 'display' value first if exists */
				this.displayLabel = selectedOption?.display
					? selectedOption?.display
					: (textContent || (await selectedOption?.getTextLabel())) ?? "";
			}
		}

		// Update validity
		setTimeout(() => {
			updateValidity(this.host);
		});
	}

	private getTextContent(element: HTMLElement) {
		if (!element) {
			return "";
		}

		return Array.from(element.childNodes)
			.filter((node) => (node as Node).nodeType === Node.TEXT_NODE)
			.map((node) => (node as Node).textContent?.trim() ?? "")
			.join(" ")
			.trim();
	}

	private handleInvalid(event: Event) {
		setValidity(false, this.host, userInteractedControls);
		emitInvalidEvent(event);
	}

	/** Sets focus on the button or input if searchable is on. */
	@Method()
	async setFocus(options?: FocusOptions) {
		if (this.searchable && !this.readonly) {
			this.editable = true;
			this.searchInput?.focus(options);
		} else {
			this.displayInput?.focus(options);
		}
	}

	@Watch("disabled")
	handleDisabledChange() {
		// Close the listbox when the control is disabled
		if (this.disabled) {
			this.open = false;
			this.handleOpenChange();
		}
	}

	@Watch("readonly")
	handleReadonlyChange() {
		if (this.readonly) {
			this.open = false;
			this.editable = false;
		}
	}

	@Watch("value")
	async handleValueChange() {
		const allOptions = this.getAllOptions();

		const value = Array.isArray(this.value) ? this.value : [this.value];

		if (this.uncontrolled || this.searchable) {
			const selectedOptions = [];
			allOptions.forEach((option) => {
				const match = value.includes(option.value);
				if (match) {
					option.selected = match;
					selectedOptions.push(option);
				} else {
					option.selected = false;
				}
			});
			this.selectedOptions = selectedOptions;
			this.tagLabels = [];

			if (this.multiType && this.variant === "tag") {
				this.selectedOptions.forEach((option) => {
					/** Make sure to honor the 'display' value first if exists */
					if (option.display) {
						this.tagLabels.push(option.display);
					} else if (option.textContent) {
						this.tagLabels.push(option.textContent);
					} else if (option.querySelector("hbr-highlight")) {
						this.tagLabels.push(option.querySelector("hbr-highlight").text);
					}
				});
			}

			/** need to clear off after adding a new option */
			if (this.variant === "tag" && this.tagLabels.length) {
				this.displayLabel = "";
				if (this.displayInput) {
					/** make sure to clear off the input value */
					this.displayInput.value = "";
				}
			}

			const selectedOption = this.selectedOptions[0];
			/** Make sure to honor the 'display' value first if exists */
			if (selectedOption?.display) {
				this.displayLabel = selectedOption?.display;
			} else {
				const highlight = selectedOption?.querySelector("hbr-highlight");
				if (highlight) {
					this.displayLabel = highlight.text;
				} else {
					const textContent = this.getTextContent(selectedOption);
					this.displayLabel =
						(textContent || (await selectedOption?.getTextLabel())) ?? "";
				}
			}
			if (!this.displayLabel && this.autocomplete && this.value) {
				this.displayLabel = this.value as string;
			}
			return;
		}
		// Select only the options that match the new value

		this.setSelectedOptions(
			allOptions
				.filter((ele) => !ele.hasAttribute("data-check"))
				.filter((el) => value.includes(el.value)),
		);

		const formValue = Array.isArray(this.value)
			? this.value.join(",")
			: this.value || null;
		this.internals?.setFormValue(formValue);
	}

	@Watch("variant")
	handleVariantChange() {
		this.multiType = this.variant === "multiple" || this.variant === "tag";
	}

	@Watch("open")
	async handleOpenChange() {
		if (this.open && this.readonly) {
			this.open = false;
			return;
		}

		if (this.open && !this.disabled) {
			// Reset the current option
			if (!this.searchable) {
				this.setCurrentOption(this.selectedOptions[0] || this.getFirstOption());
			}

			// Show
			this.hbrShow.emit();
			this.addOpenListeners();

			await stopAnimations(this.host);
			if (this.popupEl) this.popupEl.active = true;

			// Select the appropriate option based on value after the listbox opens
			requestAnimationFrame(() => {
				if (!this.currentOption) {
					//to prevent focus moving to the list box from input
					this.setCurrentOption(this.currentOption);
					/** Reset the trigger flag */
					this.eventTrigger = undefined;
				}
			});

			// const { keyframes, options } = getAnimation(this, "select.show", { dir: this.localize.dir() });
			// const { keyframes, options } = getAnimation(this.host, "select.show", {dir: ""});
			// await animateTo(this.popupEl.popup, keyframes, options);

			// Make sure the current option is scrolled into view (required for Safari)
			if (this.currentOption) {
				setTimeout(() => {
					// selected option should be visible on DOM when this get executed
					scrollIntoView(this.currentOption, this.listbox, "vertical", "auto");
					if (this.eventTrigger && this.eventTrigger !== "mouse") {
						this.currentOption.focus({ preventScroll: true });
					}
				});
			}

			this.hbrAfterShow.emit();
		} else {
			/** remove "hide" class on the help slot:
			 * we are putting form control inside of the anchor which creates an issue to push the listbox down when help slot is in display */
			const anchorEl = this.selectAnchor || this.anchorEl;
			const helpText = anchorEl?.shadowRoot.querySelector(
				".form-control__help-text",
			);
			helpText?.classList.remove("select__hide-helpText");
			const rear = anchorEl?.shadowRoot.querySelector(".form-control__rear");
			rear?.classList.remove("select__hide-rear");

			// Hide
			this.hbrHide.emit();
			this.removeOpenListeners();

			await stopAnimations(this.host);
			// const { keyframes, options } = getAnimation(this.host, "select.hide", { dir: "" });//this.localize.dir()
			// await animateTo(this.popupEl.popup, keyframes, options);
			if (this.listbox) this.listbox.hidden = true;
			if (this.popupEl) this.popupEl.active = false;

			this.hbrAfterHide.emit();
		}
	}

	@Watch("editable")
	handleEditableChange() {
		if (this.editable && !this.readonly) {
			setTimeout(() => this.searchInput?.focus());
		}
	}

	@Listen("hbr-option-click")
	handleOptionClickEvent(event: CustomEvent) {
		if (this.disabled || this.readonly) {
			return;
		}
		if (this.searchable && this.variant === "tag") {
			const mouseEvent =
				event.detail?.event ?? (event as unknown as MouseEvent);
			this.handleOptionClick(mouseEvent);
		}
	}

	/** Shows the listbox. */
	async show() {
		if (this.open || this.disabled || this.readonly) {
			this.open = false;
			return undefined;
		}

		if (this.hasDefaultSlot) {
			this.open = true;
			return waitForEvent(this.host, "hbr-after-show");
		}
	}

	/** Hides the listbox. */
	async hide() {
		if (!this.open || this.disabled) {
			this.open = false;
			return undefined;
		}

		this.open = false;
		if (this.editable) {
			this.editable = false;
			/** we need to clear off the options resulted from the search */
			if (this.searchable && !this.autocomplete) {
				this.hbrSearch.emit({ value: "" });
			}
		}

		return waitForEvent(this.host, "hbr-after-hide");
	}

	/** Checks for validity but does not show a validation message. Returns `true` when valid and `false` when invalid. */
	checkValidity() {
		return this.valueInput?.checkValidity();
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	reportValidity() {
		return this.valueInput?.reportValidity();
	}

	/** Sets a custom validation message. Pass an empty string to restore validity. */
	setCustomValidity(message: string) {
		this.valueInput?.setCustomValidity(message);
		updateValidity(this.host);
	}

	/** Sets focus on the control. */
	focusFunc(options?: FocusOptions) {
		this.displayInput?.focus(options);
	}

	/** Removes focus from the control. */
	blur() {
		this.displayInput?.blur();
	}

	setDisplayInputRef(ref) {
		this.displayInput = ref;
	}
	setSearchInputRef(ref) {
		this.searchInput = ref;
	}
	setComboboxRef(ref) {
		this.combobox = ref;
	}
	setValueInputRef(ref) {
		this.valueInput = ref;
	}

	render() {
		return (
			<Fragment>
				<hbr-popup
					ref={(el) => {
						this.popupEl = el;
					}}
					strategy={
						this.enablePopover || this.hoist || this.sync === "none"
							? "fixed"
							: "absolute"
					}
					sync={this.sync === "none" ? undefined : this.sync}
					placement={this.placement || "bottom"}
					distance={4}
					flip={true}
					shift={true}
					enablePopover={this.enablePopover}
					skidding={this.skidding}
					auto-size="vertical"
					auto-size-padding="120"
					data-component="hbr-select"
					data-external-anchor={this.anchor}
					{...(this.anchor
						? {
								anchor: this.anchor,
								composed: true,
						  }
						: {})}
					onHbr-popup-hide={this.handlePopupHide}
					onKeyDown={this.handlePopupKeydown}
				>
					{!this.anchor ? (
						<hbr-select-anchor
							{...this.anchorProps}
							slot="anchor"
							ref={(el) => {
								this.anchorEl = el;
							}}
							part="select-anchor"
							exportparts={`
							form-control,
							label-container,
							label,
							asterisk,
							element,
							help-text,
							combobox,
							combobox_tags,
							prefix,
							display-input,
							clear-button,
							expand-icon,
							counter,
							tags,
							tag__base,
							tag__prefix,
							tag__content,
							tag__remove-button,
							tag__remove-button__base
						`}
							onHbr-truncate={this.handleTruncate}
						>
							{this.variant === "tag" && this.custom && this.value?.length ? (
								<slot name="tags" slot="tags" />
							) : (
								""
							)}
							<slot name="label" slot="label">
								{this.label}
							</slot>
							<slot name="label-suffix" slot="label-suffix" />
							<slot name="label-info" slot="label-info" />
							<slot name="prefix" slot="prefix" />
							<slot name="tags" slot="tags" />
							<slot name="counter" slot="counter" />
							<slot name="counter-label" slot="counter-label" />
							{this.hasClearIconSlot ? (
								<slot name="clear-icon" slot="clear-icon" />
							) : (
								""
							)}
							{this.hasExpandIconSlot ? (
								<slot name="expand-icon" slot="expand-icon" />
							) : (
								""
							)}
							<slot name="front" slot="front" />
							<slot name="rear" slot="rear" />
							<slot name="help-text" slot="help-text">
								{this.helpText}
							</slot>
						</hbr-select-anchor>
					) : null}
					<div
						id={this.listboxId}
						role="listbox"
						aria-expanded={this.open ? "true" : "false"}
						aria-multiselectable={
							this.variant === "multiple" || this.variant === "tag"
								? "true"
								: "false"
						}
						// replacing aria-labelledby={this.labelId} with aria-label
						// since labelId is located inside of the anchor component which can't be reached due to the shadow dom
						aria-label={this.arialabel || this.label}
						part="listbox"
						class={`select__listbox${this.truncate ? " select__truncate" : ""}`}
						tabindex="-1"
						onMouseUp={
							!(this.searchable && this.variant === "tag")
								? this.handleOptionClick
								: null
						}
						ref={(el) => {
							this.listbox = el;
						}}
					>
						<slot onSlotchange={this.handleDefaultSlotChange} />
					</div>
				</hbr-popup>
				{this.truncateContent ? (
					<hbr-tooltip
						content={this.truncateContent}
						anchor={this.getTooltipAnchor()}
						class={"select--anchor-tooltip"}
					/>
				) : null}
			</Fragment>
		);
	}
}

setDefaultAnimation("select.show", {
	keyframes: [
		{ opacity: 0, scale: 0.9 },
		{ opacity: 1, scale: 1 },
	],
	options: { duration: 100, easing: "ease" },
});

setDefaultAnimation("select.hide", {
	keyframes: [
		{ opacity: 1, scale: 1 },
		{ opacity: 0, scale: 0.9 },
	],
	options: { duration: 100, easing: "ease" },
});
