import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { eye, eyeSlash, xCircle } from "../../../icons";
import FormControl from "../../functional-components/form-control/form-control";
import { attachElementInternals } from "../../utils/element-internals";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";
import type { Aria, i18n } from "./types";

let id = 0;

/**
 * @since 0.0.10
 * @status stable
 *
 * @description Use text input fields to input text or numbers. They can offer great flexibility or be constrained in design or by data validation. Advanced input fields allow for autocompletion.
 *
 * @slot label - The input's label. Alternatively, you can use the label prop.
 * @slot label-suffix - Non-interactive content to display inline with the input label.
 * @slot label-info - Interactive informational content, such as a tooltip trigger, displayed next to the input label.
 * @slot prefix - Used to prepend an icon or similar element to the input.
 * @slot suffix - Used to append an icon or similar element to the input.
 * @slot trailing - Used to place content to the side of the input within the same row.
 * @slot clear-icon - An icon to use in lieu of the default clear icon.
 * @slot show-password-icon - An icon to use in lieu of the default show password icon.
 * @slot hide-password-icon - An icon to use in lieu of the default hide password icon.
 * @slot help-text - Help text that describes how to use the input. Alternatively, you can use the help-text prop.
 *
 * @part base - The component's base wrapper.
 * @part form-control - The form control that wraps the label, input, and help-text.
 * @part label-container - The container that wraps the label and label-info slot.
 * @part label - The input label.
 * @part input - The input control.
 * @part prefix - The input prefix container.
 * @part clear-button - The clear button.
 * @part password-toggle-button - The password toggle button.
 * @part suffix - The input suffix container.
 * @part trailing - The input trailing container.
 * @part help-text - The input help text.
 */

@Component({
	tag: "hbr-input",
	styleUrl: "input.scss",
	shadow: true,
	formAssociated: true,
})
export class Input {
	inputId = `input-${++id}`;
	labelId = `input-label-${id}`;
	suffixId = `input-suffix-label--${id}`;
	prefixId = `input-prefix-label--${id}`;
	helpTextId = `input-help-text-${id}`;
	input: HTMLInputElement;
	private defaultAria: Aria = {
		clear: "delete input content",
	};

	private defaultI18n: i18n = {
		show: "Show",
		hide: "Hide",
		invalidFeedback: "Invalid Input",
	};

	private internals?: ElementInternals;

	@Element() host: HTMLHbrInputElement;

	@State() hasFocus = false;
	@State() hasHelpTextSlot = false;
	@State() hasLabelSlot = false;
	@State() hasLabelInfoSlot = false;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;
	@State() hasTrailingSlot = false;
	@State() hasElementSuffix = false;
	@State() hasPrefixSlot = false;
	@State() hasSuffixSlot = false;
	@State() isPasswordVisible = false;
	@State() library = "hbr-theme-magnetic";
	@State() requiredAfterFocus = false;

	/**
	 * The type of input. Works the same as a native `<input>` element, but only a subset of types are supported. Defaults
	 * to `text`. Use a number input field to input a number within a certain range using the mouse or keyboard.
	 */
	@Prop({ reflect: true }) type:
		| "date"
		| "email"
		| "number"
		| "password"
		| "search"
		| "tel"
		| "text"
		| "time"
		| "datetime-local"
		| "url" = "text";

	/** The input's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** The name of the input, submitted as a name/value pair with form data. */
	@Prop({ reflect: true }) name = "";

	/** The current value of the input, submitted as a name/value pair with form data. */
	@Prop({ mutable: true }) value = "";

	/** Draws a pill-style input with rounded edges. */
	@Prop({ reflect: true }) pill = false;

	/** The input's label. If you need to display HTML, use the `label` slot instead. */
	@Prop() label = "";

	/** The input's help text. If you need to display HTML, use the `help-text` slot instead. */
	@Prop() helpText = "";

	/** Placeholder text to show as a hint when the input is empty. */
	@Prop({ mutable: true }) placeholder: string;

	/** Disables the input. */
	@Prop({ reflect: true }) disabled = false;

	/** Makes the input not mutable, meaning the user can not edit the control. */
	@Prop({ reflect: true }) readonly = false;

	/** The minimum length of input that will be considered valid. */
	@Prop({ reflect: true }) minlength: number;

	/** The maximum length of input that will be considered valid. */
	@Prop({ reflect: true }) maxlength: number;

	/** The input's minimum value. Only applies to date and number input types. */
	@Prop({ reflect: true }) min: number | string;

	/** The input's maximum value. Only applies to date and number input types. */
	@Prop({ reflect: true }) max: number | string;

	/**
	 * Specifies the granularity that the value must adhere to, or the special value `any` which means no stepping is
	 * implied, allowing any numeric value. Only applies to date and number input types.
	 */
	@Prop({ reflect: true }) step: number | "any";

	/** A regular expression pattern to validate input against. */
	@Prop({ reflect: true }) pattern: string;

	/** Makes the input a required field. */
	@Prop({ reflect: true }) required: boolean;

	/**
	 * This will be true when the control is in an invalid state. Validity is determined by props such as `type`,
	 * `required`, `minlength`, `maxlength`, and `pattern` using the browser's constraint validation API.
	 */
	@Prop({ mutable: true, reflect: true }) invalid = false;

	/** Controls whether and how text input is automatically capitalized as it is entered by the user. */
	@Prop() autocapitalize:
		| "off"
		| "none"
		| "on"
		| "sentences"
		| "words"
		| "characters";

	/** Indicates whether the browser's autocorrect feature is on or off. */
	@Prop() autocorrect: string;

	/**
	 * Specifies what permission the browser has to provide assistance in filling out form field values. Refer to
	 * [this page on MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/autocomplete) for available values.
	 */
	@Prop() autocomplete: string;

	/** Indicates that the input should receive focus on page load. */
	@Prop() autofocus: boolean;

	/** Enables spell checking on the input. */
	@Prop() spellcheck: boolean;

	/** Adds a clear button when the input is not empty. */
	@Prop() clearable = false;

	/** Set to true to add a password toggle button for password inputs. */
	@Prop() togglePassword = false;

	/** optional attributes since v.2.14.13 */
	@Prop() attr: { [key: string]: string | number | boolean } = {};

	/**
	 * Tells the browser what type of data will be entered by the user, allowing it to display the appropriate virtual
	 * keyboard on supportive devices.
	 */
	@Prop() inputmode:
		| "none"
		| "text"
		| "decimal"
		| "numeric"
		| "tel"
		| "search"
		| "email"
		| "url";

	/** Indicates that the input has an error */
	@Prop() error = false;

	/** 'aria-label' attribute when a label is not set. Use "aria={label: value}" instead.  */
	@Prop() arialabel: string;

	/** Aria role attribute like role="combobox". Use "aria={role: value}" instead. */
	@Prop() ariarole: string;

	/** Aria expanded attribute. Use "aria={expanded: value}" instead. */
	@Prop() ariaexpanded: string;

	/** Tooltip content if the icon button serves as a tooltip reference. */
	@Prop({ reflect: true }) tooltip: string;

	/** Attributes related to screen readers. */
	@Prop() aria: Aria;

	/** The i18n (internationalization) key-value pairs. */
	@Prop() i18n: i18n;

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	@Watch("value")
	handleValueChange() {
		// In rare cases, the watcher may be called before render so we need to make sure the input exists
		this.invalid = this.input ? !this.input.checkValidity() : false;
	}

	@Watch("disabled")
	handleDisabledChange() {
		if (this.input) {
			// Disabled form controls are always valid, so we need to recheck validity when the state changes
			this.input.disabled = this.disabled;
			this.invalid = !this.input.checkValidity();
		}
	}

	/** Emitted when the control's value changes. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter;

	/** Emitted when the clear button is activated. */
	@Event({ eventName: "hbr-clear" }) hbrClear: EventEmitter;

	/** Emitted when the control receives input. */
	@Event({ eventName: "hbr-input" }) hbrInput: EventEmitter;

	/** Emitted when the control gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	/** Emitted when the control loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	// /** Emitted when the control becomes invalid. */
	// @Event({ eventName: "hbr-invalid" }) hbrInvalid: EventEmitter;

	connectedCallback() {
		this.handleChange = this.handleChange.bind(this);
		this.handleInput = this.handleInput.bind(this);
		this.handleInvalid = this.handleInvalid.bind(this);
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleBaseClick = this.handleBaseClick.bind(this);
		this.handleClearClick = this.handleClearClick.bind(this);
		this.handlePasswordToggle = this.handlePasswordToggle.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleDisabledChange = this.handleDisabledChange.bind(this);

		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);

		this.internals ??= attachElementInternals(this.host);
	}
	componentWillLoad() {
		this.handleSlotChange();

		//Replacing with :has pseudo class. If native input is invalid, red border will be set.
		//this.invalid = !this.input?.checkValidity();
	}

	disconnectedCallback() {
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	/** Sets focus on the input. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.input.focus(options);
	}

	/** Removes focus from the input. */
	@Method()
	async removeFocus() {
		this.input.blur();
	}

	/** Selects all the text in the input. */
	@Method()
	async select() {
		return this.input.select();
	}

	/** Sets the start and end positions of the text selection (0-based). */
	@Method()
	async setSelectionRange(
		selectionStart: number,
		selectionEnd: number,
		selectionDirection: "forward" | "backward" | "none" = "none",
	) {
		return this.input.setSelectionRange(
			selectionStart,
			selectionEnd,
			selectionDirection,
		);
	}

	/** Replaces a range of text with a new string. */
	@Method()
	async setRangeText(
		replacement: string,
		start: number,
		end: number,
		selectMode: "select" | "start" | "end" | "preserve" = "preserve",
	) {
		this.input.setRangeText(replacement, start, end, selectMode);

		if (this.value !== this.input.value) {
			this.value = this.getInputValue();
			this.hbrChange.emit();
			this.hbrInput.emit();
		}
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	@Method()
	async reportValidity() {
		// this method shows the native browser validation tooltip.
		return this.input.reportValidity();
	}

	/** Checks for validity but does not show a validation message. Returns `true` when valid and `false` when invalid. */
	@Method()
	async checkValidity() {
		return this.input.checkValidity();
	}

	/** Sets a custom validation message. If `message` is not empty, the field will be considered invalid. */
	@Method()
	async setCustomValidity(message: string) {
		this.input.setCustomValidity(message);
		this.invalid = !this.input.checkValidity();
	}

	handleChange(event?: Event) {
		this.value = this.getInputValue(event);
		this.internals?.setFormValue(this.getInputValue(event));
		this.hbrChange.emit();
	}
	isValidNumber(input: string) {
		// support floating number, and negative number
		return /^-?\d*\.?\d+$/.test(input);
	}
	getInputValue = (event?: Event) => {
		const inputData = (event as InputEvent)?.data;
		const inputElement =
			this.input ?? (event?.target as HTMLInputElement | null);
		const inputValue = inputElement?.value ?? "";

		if (this.type === "number") {
			// https://github.com/cisco-harbor/elements/issues/3475
			if (
				inputData !== "-" &&
				inputData !== "+" &&
				!this.isValidNumber(inputValue) &&
				this.input
			) {
				this.input.value = "";
			}
		}
		return inputValue;
	};
	handleInput(event?: Event) {
		this.value = this.getInputValue(event);
		this.internals?.setFormValue(this.value || null);
		if (this.required) this.requiredAfterFocus = true;
		this.hbrInput.emit();
	}

	handleInvalid(event: Event) {
		/**
		 * The oninvalid event is emitted when a submittable element is checked for validity and fails to satisfy its constraints.
		 * This typically occurs in the following scenarios:
		 * - Form Submission:
		 * When a form containing the invalid input is submitted, the invalid event is fired on each individual form control that does not meet its validation criteria
		 * - Explicit Validity Check:
		 * When checkValidity() or reportValidity() methods are explicitly called on the input element or its containing form, and the input's value does not pass validation.
		 */

		// Prevent the native browser validation tooltip from appearing
		event.preventDefault();
		this.invalid = true;
		// this.hbrInvalid.emit({invalid: true});
	}

	handleBlur() {
		this.hasFocus = false;
		this.host.setAttribute("data-focused", "false");
		this.hbrBlur.emit();
	}

	handleFocus() {
		this.hasFocus = true;
		this.host.setAttribute("data-focused", "true");
		this.hbrFocus.emit();
	}

	handleBaseClick(event: MouseEvent) {
		if (this.disabled || this.readonly) return;

		const target = event.composedPath()[0] as HTMLElement;
		const interactiveTarget = target.closest?.(
			"button, a, input, select, textarea, hbr-icon-button, [role='button'], [tabindex]",
		);

		if (interactiveTarget) return;

		this.input.focus();
	}

	handleClearClick(event: MouseEvent) {
		this.value = "";
		this.hbrClear.emit();
		this.hbrInput.emit();
		this.hbrChange.emit();
		this.input.focus();

		event.stopPropagation();
	}

	handlePasswordToggle() {
		this.isPasswordVisible = !this.isPasswordVisible;
	}

	handleSlotChange() {
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasLabelSlot = hasSlot(this.host, "label");
		this.hasLabelInfoSlot = hasSlot(this.host, "label-info");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");
		this.hasTrailingSlot = hasSlot(this.host, "trailing");
		this.hasElementSuffix = hasSlot(this.host, "element-suffix");
		this.hasPrefixSlot = hasSlot(this.host, "prefix");
		this.hasSuffixSlot = hasSlot(this.host, "suffix");
	}
	render() {
		const describedHelpId =
			this.helpText || this.hasHelpTextSlot ? this.helpTextId : "";
		const tooltipId = this.tooltip ? `${this.inputId}-tooltip` : "";
		const describedId =
			describedHelpId || tooltipId
				? `${describedHelpId} ${tooltipId}`
				: undefined;

		const optionalProps = {
			//due to the biome error on input autofocus
			autoFocus: this.autofocus,
			// Apply attributes from attr prop to the input element
			...this.attr,
		};

		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const { arialabel, ariarole, ariaexpanded, aria } = this;
		const { label, describedby, invalid, role, expanded } = aria || {};

		const _aria = { ...this.defaultAria, ...this.aria };
		const _i18n = { ...this.defaultI18n, ...this.i18n };
		const { show, hide } = _i18n;

		const a11y = {
			"aria-label": label || arialabel,
			"aria-describedby": describedby || describedId,
			"aria-invalid": invalid || this.invalid ? "true" : "false",
			role: role || ariarole,
			"aria-expanded": expanded || ariaexpanded,
		};

		const isEmpty = [null, undefined, ""].includes(this.value);
		const hasClearIcon = this.clearable && !this.disabled && !this.readonly;
		const showClearIcon =
			hasClearIcon && (typeof this.value === "number" || this.value.length > 0);

		return (
			<FormControl
				inputId={this.inputId}
				label={this.label}
				labelId={this.labelId}
				hasLabelSlot={this.hasLabelSlot}
				hasLabelInfoSlot={this.hasLabelInfoSlot}
				hasFrontSlot={this.hasFrontSlot}
				hasRearSlot={this.hasRearSlot}
				hasTrailingSlot={this.hasTrailingSlot}
				hasElementSuffix={this.hasElementSuffix}
				helpTextId={this.helpTextId}
				helpText={this.helpText}
				hasHelpTextSlot={this.hasHelpTextSlot}
				size={this.size}
				source={"input"}
				hasFocus={this.hasFocus}
				hasValue={this.value?.length > 0}
				hasError={this.error}
				isDisabled={this.disabled}
				isRequired={this.required}
				tooltip={this.tooltip}
				tooltipId={this.tooltip ? `${this.inputId}-tooltip` : undefined}
			>
				<div
					part={`base ${this.error ? " error" : ""}`}
					onClick={this.handleBaseClick}
					class={{
						input: true,

						// Sizes
						"input--small": this.size === "small",
						"input--medium": this.size === "medium",
						"input--large": this.size === "large",

						// States
						"input--pill": this.pill,
						"input--has-prefix": this.hasPrefixSlot,
						"input--has-suffix": this.hasSuffixSlot,
						"input--has-clear": showClearIcon,
						"input--disabled": this.disabled,
						"input--focused": this.hasFocus,
						"input--empty": isEmpty,
						"input--invalid": this.invalid,
						"input--error": this.error,
						"input--readonly": this.readonly,
						[`input--${this.type}`]: true,
					}}
				>
					<span part="prefix" class="input__prefix" id={this.prefixId}>
						<slot name="prefix" />
					</span>

					<input
						part="input"
						ref={(el) => {
							this.input = el;
						}}
						{...(this.attr?.id ? {} : { id: this.inputId })}
						class={`input__control ${this.type === "number" ? "number" : ""}`}
						type={
							this.type === "password" && this.isPasswordVisible
								? "text"
								: this.type
						}
						name={this.name}
						placeholder={this.placeholder}
						disabled={this.disabled}
						readonly={this.readonly}
						minLength={this.minlength}
						maxLength={this.maxlength}
						min={this.min}
						max={this.max}
						step={this.step}
						value={this.value}
						autoCapitalize={this.autocapitalize}
						autoComplete={this.autocomplete}
						autoCorrect={this.autocorrect}
						{...optionalProps}
						spellcheck={this.spellcheck}
						pattern={this.pattern}
						required={this.requiredAfterFocus}
						inputMode={this.inputmode}
						onChange={this.handleChange}
						onInput={this.handleInput}
						onInvalid={this.handleInvalid}
						{...(this.type === "time" ? { title: "" } : null)} //hide the native validation tooltip (time shows validation tooltip even on keydown without submitting)
						onFocus={this.handleFocus}
						onBlur={this.handleBlur}
						{...a11y}
					/>

					{showClearIcon && (
						<button
							part="clear-button"
							class="input__clear"
							type="button"
							aria-label={_aria.clear}
							onClick={this.handleClearClick}
						>
							<slot name="clear-icon">
								<hbr-icon asset={customSystemIcons?.["x-circle"] || xCircle} />
							</slot>
						</button>
					)}

					{this.invalid && (
						<hbr-visually-hidden>
							<div class="hidden" aria-live="polite" aria-atomic="true">
								{_i18n.invalidFeedback}
							</div>
						</hbr-visually-hidden>
					)}

					{this.togglePassword && (
						<button
							part="password-toggle-button"
							class="input__password-toggle"
							type="button"
							onClick={this.handlePasswordToggle}
						>
							{this.isPasswordVisible ? (
								<slot name="show-password-icon">
									{this.library === "hbr-theme-cohesion" && (
										<hbr-icon
											asset={customSystemIcons?.["eye-slash"] || eyeSlash}
										/>
									)}
									{this.library === "hbr-theme-cohesion-v1" && (
										<span class={`input__password-show-hide-${this.size}`}>
											{hide.toUpperCase()}
										</span>
									)}
									{this.library === "hbr-theme-magnetic" && (
										<span
											class={`input__password-show-hide-${this.size}-magnetic`}
										>
											{hide}
										</span>
									)}
								</slot>
							) : (
								<slot name="hide-password-icon">
									{this.library === "hbr-theme-cohesion" && (
										<hbr-icon asset={customSystemIcons?.eye || eye} />
									)}
									{this.library === "hbr-theme-cohesion-v1" && (
										<span class={`input__password-show-hide-${this.size}`}>
											{show.toUpperCase()}
										</span>
									)}
									{this.library === "hbr-theme-magnetic" && (
										<span
											class={`input__password-show-hide-${this.size}-magnetic`}
										>
											{show}
										</span>
									)}
								</slot>
							)}
						</button>
					)}

					<span part="suffix" class="input__suffix" id={this.suffixId}>
						<slot name="suffix" />
					</span>
				</div>
			</FormControl>
		);
	}
}
