import { Component, Event, EventEmitter, Prop, State, h } from "@stencil/core";
import { caretDown, xCircle } from "../../../icons";
import FormControl from "../../functional-components/form-control/form-control";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

/**
 * @since 2.0
 * @status stable
 * @slot label - The input's label. Alternatively, you can use the `label` attribute.
 * @slot label-suffix - Non-interactive content to display inline with the input label.
 * @slot label-info - Interactive informational content, such as a tooltip trigger, displayed next to the input label.
 * @slot prefix - Used to prepend a presentational icon or similar element to the combobox.
 * @slot tags - The container that houses option tags when `multiselect` is used.
 * @slot counter - The number of selected options when `multiselect` is used.
 * @slot counter-label - The label of number of selected options when `multiselect` is used.
 * @slot clear-icon - An icon to use in lieu of the default clear icon.
 * @slot expand-icon - The icon to show when the control is expanded and collapsed. Rotates on open and close.
 * @slot help-text - Text that describes how to use the input. Alternatively, you can use the `help-text` attribute.
 * @slot front - Used a presentational slot between label and main content in the form element.
 * @slot rear - Used a presentational slot append to the back of the form element.
 *
 * @part combobox - The container the wraps the prefix, combobox, clear icon, and expand button.
 * @part prefix -  The container that wraps the prefix slot.
 * @part label-container - The container that wraps the label and label-info slot.
 * @part label - The input label.
 * @part counter - The number of selected options element.
 * @part display-input - The element that displays the selected option's label, an `<input>` element.
 * @part tags - The container that houses option tags when `multiselect` is used.
 * @part tag - The individual tags that represent each multiselect option.
 * @part tag__base - The tag's base part.
 * @part tag__prefix - The tag's prefix part.
 * @part tag__content - The tag's content part.
 * @part tag__remove-button - The tag's remove button.
 * @part tag__remove-button__base - The tag's remove button base part.
 * @part clear-button - The clear button.
 * @part clear-icon - The clear button.
 * @part expand-icon - The container that wraps the expand icon.
 * @part front - Placed between label and main content in the form element.
 * @part rear - Placed after the form element before the help text.
 * @part help-text - The help text wrapper element
 */

@Component({
	tag: "hbr-select-anchor",
	styleUrl: "select-anchor.scss",
	shadow: true,
})
export class SelectAnchor {
	/** The name of the select, submitted as a name/value pair with form data. */
	@Prop() name: string;

	@Prop({ mutable: true }) value: string | string[] = "";

	/** variant "multi select or tag". With this enabled, value will be an array. */
	@Prop({ reflect: true }) variant: "single" | "multiple" | "tag" = "single";

	/** The select's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** Placeholder text to show as a hint when the select is empty. */
	@Prop() placeholder: string;

	/** Allows more than one option to be selected. */
	@Prop({ reflect: true }) multiple = false;

	/**
	 * The maximum number of selected options to show when `multiple` is true. After the maximum, "+n" will be shown to
	 * indicate the number of additional items that are selected. Set to 0 to remove the limit.
	 */
	// @Prop({attribute: "max-options-visible"}) maxOptionsVisible: number = 3;

	/** Disables the select control. */
	@Prop({ reflect: true }) disabled = false;

	/** Adds a clear button when the select is not empty. */
	@Prop() clearable = false;

	/**
	 * Indicates whether or not the select is open. You can toggle this attribute to show and hide the menu, or you can
	 * use the `show()` and `hide()` methods and this attribute will reflect the select's open state.
	 */
	@Prop({ reflect: true, mutable: true }) open = false;

	/**
	 * Enable this option to prevent the listbox from being clipped when the component is placed inside a container with
	 * `overflow: auto|scroll`. Hoisting uses a fixed positioning strategy that works in many, but not all, scenarios.
	 */
	@Prop() hoist = false;

	/** Draws a filled select. */
	@Prop({ reflect: true }) filled = false;

	/** Draws a pill-style select with rounded edges. */
	@Prop({ reflect: true }) pill = false;

	/** The select's label. If you need to display HTML, use the `label` slot instead. */
	@Prop() label = "";

	/** For SR when there is no label */
	@Prop() arialabel: string;

	@Prop() displayLabel = "";

	@Prop() selectedOptions = [];

	@Prop() readonly = false;

	/**
	 * The preferred placement of the select's menu. Note that the actual placement may vary as needed to keep the listbox
	 * inside of the viewport.
	 */
	@Prop({ reflect: true }) placement: "top" | "bottom" = "bottom";

	/** The select's help text. If you need to display HTML, use the `help-text` slot instead. */
	@Prop({ attribute: "help-text" }) helpText = "";

	/** The select's required attribute. */
	@Prop({ reflect: true }) required = false;

	/** error state */
	@Prop() error = false;

	@Prop() inputId: string;

	@Prop() labelId: string;

	@Prop() listboxId: string;

	@Prop() helpTextId: string;

	@Prop() cssClass: object;

	@Prop() hasLabel: boolean;
	@Prop() hasLabelSlot: boolean;
	@Prop() hasLabelInfoSlot: boolean;
	@Prop() hasHelpText: boolean;
	@Prop() hasHelpTextSlot: boolean;
	@Prop() hasFrontSlot: boolean;
	@Prop() hasRearSlot: boolean;
	@Prop() hasClearIcon: boolean;
	@Prop() showPrefix: boolean;
	@Prop() hideInput: boolean;
	@Prop() hasCounterSlot: boolean;

	@Prop() handleLabelClick: (event) => void;
	@Prop() handleHelpSlotChange: (event) => void;
	@Prop() handleComboboxKeyDown: (event) => void;
	@Prop() handleComboboxMouseDown: (event) => void;
	@Prop() handleFocus: (event) => void;
	@Prop() handleKeyUp: (event) => void;
	@Prop() handleBlur: (event) => void;
	@Prop() handleSearch: (event) => void;
	@Prop() handleInvalid: () => void;
	@Prop() handleClearMouseDown: (event) => void;
	@Prop() handleClearClick: (event) => void;
	@Prop() handleTagRemove: (option, event) => void;
	@Prop() toggleOptionSelection: (option, force?: boolean) => void;

	@Prop() setDisplayInputRef: (
		elm?: HTMLInputElement | HTMLSpanElement,
	) => void;
	@Prop() setSearchInputRef: (elm?: HTMLInputElement) => void;
	@Prop() setComboboxRef: (elm?: HTMLInputElement) => void;
	@Prop() setValueInputRef: (elm?: HTMLInputElement) => void;
	@Prop() focusFunc: () => void;
	@Prop() cssClasses = {};
	@Prop() truncate = false;
	@Prop() searchable: boolean;
	@Prop() custom: boolean;
	@Prop() tooltip: string;
	@Prop() autocomplete: boolean;
	@Prop() autofocus: boolean;
	/* Set to true to control the anchor's state from the application / framework's side */
	@Prop() uncontrolled: boolean;
	@Prop() search: string;
	@Prop() editable: boolean;
	@Prop() tagWrap: boolean;
	@Prop({ reflect: true }) lines?: number;
	@Prop() tagLabels: string[];
	/** The i18n (internationalization) key-value pairs. */
	@Prop() i18n: { clearEntry: string };
	/** Indicate whether the event is initiated by a keyboard or a mouse. */
	@Prop() eventTrigger: string;
	@Prop() displayInput: HTMLInputElement | HTMLSpanElement;

	@State() private measuredTagMaxHeight?: string;

	private resizeObserver?: ResizeObserver;
	private tagsEl?: HTMLDivElement;
	private pendingMeasurementFrame?: number;

	/** Emitted when the content of the select is truncated. */
	@Event({ eventName: "hbr-truncate" }) hbrTruncate!: EventEmitter<{
		truncated: boolean;
		content: string;
	}>;

	componentDidRender() {
		this.scheduleMeasuredTagMaxHeightSync();

		const isTruncated =
			this.displayInput?.scrollWidth > this.displayInput?.clientWidth;
		if (isTruncated) {
			this.hbrTruncate.emit({
				truncated: true,
				content:
					this.displayLabel ||
					(typeof this.value === "string" ? this.value : ""),
			});
		} else {
			this.hbrTruncate.emit({
				truncated: false,
				content: "",
			});
		}
	}

	componentDidLoad() {
		if (!this.hasLinesLimit()) return;

		this.resizeObserver = new ResizeObserver(() => {
			this.scheduleMeasuredTagMaxHeightSync();
		});

		if (this.comboboxRef) this.resizeObserver.observe(this.comboboxRef);
		if (this.tagsEl) this.resizeObserver.observe(this.tagsEl);
	}

	disconnectedCallback() {
		if (this.pendingMeasurementFrame) {
			cancelAnimationFrame(this.pendingMeasurementFrame);
			this.pendingMeasurementFrame = undefined;
		}
		this.resizeObserver?.disconnect();
	}

	private handleTagRemoveLocal(option, event) {
		this.handleTagRemove(option, event);
	}

	private defaultI18n = {
		clearEntry: "Clear entry",
	};

	private comboboxRef?: HTMLDivElement;

	private hasLinesLimit() {
		return this.variant === "tag" && !!this.lines && this.lines >= 1;
	}

	private setTagsRef = (elm?: HTMLDivElement) => {
		this.tagsEl = elm;
	};

	private setLocalComboboxRef = (elm?: HTMLDivElement) => {
		this.comboboxRef = elm;
		if (typeof this.setComboboxRef === "function") {
			this.setComboboxRef(elm as HTMLInputElement);
		}
	};

	private scheduleMeasuredTagMaxHeightSync() {
		if (!this.hasLinesLimit()) return;
		if (this.pendingMeasurementFrame !== undefined) {
			cancelAnimationFrame(this.pendingMeasurementFrame);
		}
		this.pendingMeasurementFrame = requestAnimationFrame(() =>
			this.syncMeasuredTagMaxHeight(),
		);
	}

	private syncMeasuredTagMaxHeight() {
		const { comboboxRef, tagsEl, lines } = this;
		if (!comboboxRef || !tagsEl) return;

		const saved = comboboxRef.style.maxHeight;
		comboboxRef.style.maxHeight = "none";

		const slot = tagsEl.querySelector(
			'slot[name="tags"]',
		) as HTMLSlotElement | null;
		const items = (
			slot ? slot.assignedElements({ flatten: true }) : [...tagsEl.children]
		).filter(
			(el): el is HTMLElement =>
				el instanceof HTMLElement && el.offsetParent !== null,
		);

		const tagsTop = tagsEl.getBoundingClientRect().top;
		const rowBottoms = new Map<number, number>();
		for (const item of items) {
			const rect = item.getBoundingClientRect();
			const rowTop = Math.round(rect.top - tagsTop);
			rowBottoms.set(
				rowTop,
				Math.max(rowBottoms.get(rowTop) ?? 0, rect.bottom - tagsTop),
			);
		}

		const visibleRows = [...rowBottoms.entries()]
			.sort(([a], [b]) => a - b)
			.slice(0, lines);
		comboboxRef.style.maxHeight = saved;

		if (!visibleRows.length) {
			this.measuredTagMaxHeight = undefined;
			return;
		}

		const visibleBottom = Math.max(...visibleRows.map(([, b]) => b));
		const { borderTopWidth, borderBottomWidth } = getComputedStyle(comboboxRef);
		const border =
			parseFloat(borderTopWidth || "0") + parseFloat(borderBottomWidth || "0");
		const next = `${Math.ceil(
			visibleBottom + comboboxRef.scrollHeight - tagsEl.scrollHeight + border,
		)}px`;
		if (this.measuredTagMaxHeight !== next) this.measuredTagMaxHeight = next;
	}

	private getLineStyle() {
		if (!this.hasLinesLimit()) return undefined;
		return {
			"--select-tag-lines": `${this.lines}`,
			...(this.measuredTagMaxHeight
				? { maxHeight: this.measuredTagMaxHeight }
				: {}),
		};
	}

	private searchInputElement = (
		editPlaceholder: string,
		describedId: string,
		prop: object,
	) => {
		return (
			<input
				part="search-input"
				class="select__search-input"
				type="search"
				placeholder={editPlaceholder}
				disabled={this.disabled}
				autocomplete="off"
				spellcheck="false"
				autocapitalize="off"
				readonly={false}
				aria-controls={this.listboxId}
				aria-expanded={this.open ? "true" : "false"}
				aria-haspopup="listbox"
				aria-disabled={this.disabled ? "true" : "false"}
				aria-readonly={this.readonly ? "true" : "false"}
				aria-describedby={describedId}
				role="combobox"
				tabIndex={0}
				onFocus={this.handleFocus}
				onBlur={this.handleBlur}
				onInput={this.handleSearch}
				ref={this.setSearchInputRef}
				id={this.inputId}
				onKeyUp={this.handleKeyUp}
				value={this.autocomplete ? this.value : null}
				{...prop}
			/>
		);
	};
	private readonlyInputElement = (readonlyValue, describedId, prop) => {
		if (this.variant === "single" && !this.uncontrolled) {
			return (
				<span
					part="display-input"
					class={`select__display-input span ${
						!this.value ? "placeholder" : ""
					}`}
					aria-controls={this.listboxId}
					aria-expanded={this.open ? "true" : "false"}
					aria-haspopup="listbox"
					aria-disabled={this.disabled ? "true" : "false"}
					aria-readonly={this.readonly ? "true" : "false"}
					aria-describedby={describedId}
					role="combobox"
					tabIndex={0}
					onFocus={this.handleFocus}
					onBlur={this.handleBlur}
					ref={this.setDisplayInputRef}
					id={this.inputId}
					onKeyUp={this.handleKeyUp}
					{...prop}
				>
					{this.value ? readonlyValue : this.placeholder}
				</span>
			);
		}

		return (
			<input
				part="display-input"
				class={`select__display-input input${
					this.hideInput ? " hideInput-tag" : ""
				}`}
				type="text"
				placeholder={this.placeholder}
				disabled={this.disabled}
				value={readonlyValue}
				autocomplete="off"
				spellcheck="false"
				autocapitalize="off"
				readonly={true}
				aria-controls={this.listboxId}
				aria-expanded={this.open ? "true" : "false"}
				aria-haspopup="listbox"
				aria-disabled={this.disabled ? "true" : "false"}
				aria-readonly={this.readonly ? "true" : "false"}
				aria-describedby={describedId}
				role="combobox"
				tabIndex={0}
				onFocus={this.handleFocus}
				onBlur={this.handleBlur}
				ref={this.setDisplayInputRef}
				id={this.inputId}
				onKeyUp={this.handleKeyUp}
				{...prop}
			/>
		);
	};
	private selectedTagsInDisplay = (
		tagRemove: boolean,
		obj?: {
			editPlaceholder: string;
			describedId: string;
			prop: object;
		},
	) => {
		return (
			<div
				part="tags"
				class={{
					select__tags: true,
					"select__tags-custom": this.custom,
				}}
				ref={this.setTagsRef}
			>
				{this.custom ? (
					<slot name="tags" />
				) : (
					this.selectedOptions?.map((option, index) => {
						const prefixElement = option.querySelector('[slot="prefix"]');
						const tagLabel = this.editable ? this.tagLabels[index] : "";

						return (
							<hbr-tag
								part="tag"
								exportparts="
								base:tag__base,
								prefix: tag__prefix,
								content:tag__content,
								remove-button:tag__remove-button,
								remove-button__base:tag__remove-button__base
							"
								pill={this.pill}
								size={this.size}
								removable={!this.readonly ? tagRemove : undefined}
								onHbr-remove={this.handleTagRemoveLocal.bind(this, option)}
								class={"select-anchor__tag"}
								wrap={this.tagWrap}
							>
								{prefixElement?.tagName.toLowerCase() === "hbr-icon" ? (
									<hbr-icon name={prefixElement.name} slot="prefix" />
								) : (
									""
								)}
								<span class={"select-anchor__tag-text-slot"}>
									{tagLabel ||
										option.display ||
										option.textContent ||
										option.querySelector("hbr-highlight")?.text}
								</span>
							</hbr-tag>
						);
					})
				)}
				{this.uncontrolled && (
					<span
						class={{
							"select-anchor__tag-searchInput": this.editable,
							"select-anchor__tag-displayInput": !this.editable,
							"select-anchor__tag-has-value": this.value?.length > 0,
						}}
					>
						{this.editable
							? this.searchInputElement(
									obj.editPlaceholder,
									obj.describedId,
									obj.prop,
							  )
							: this.readonlyInputElement(
									obj.editPlaceholder,
									obj.describedId,
									obj.prop,
							  )}
					</span>
				)}
			</div>
		);
	};

	render() {
		const prop: { "aria-label"?: string; "aria-labelledby"?: string } = {};
		const tagRemove = !this.readonly;
		const multiSelected = this.variant !== "single" && !!this.value?.length;
		const hasLabel = this.label || this.hasLabelSlot;
		const fallbackLabel = this.arialabel || this.placeholder;
		if (multiSelected) {
			if (!this.searchable) {
				const baseLabel = this.label || fallbackLabel;
				prop["aria-label"] = baseLabel
					? `${this.value?.length} ${baseLabel} selected`
					: `${this.value?.length} selected`;
			} else if (hasLabel) {
				prop["aria-labelledby"] = this.labelId;
			} else if (fallbackLabel) {
				prop["aria-label"] = fallbackLabel;
			}
		} else {
			if (hasLabel) {
				prop["aria-labelledby"] = this.labelId;
			} else if (fallbackLabel) {
				prop["aria-label"] = fallbackLabel;
			}
		}

		const describedHelpId = this.helpTextId ? this.helpTextId : "";
		const tooltipId = this.tooltip ? `${this.inputId}-tooltip` : "";
		const describedId =
			describedHelpId || tooltipId
				? `${describedHelpId} ${tooltipId}`
				: undefined;

		let editPlaceholder = this.placeholder;

		if (
			this.value &&
			typeof this.value === "string" &&
			typeof this.placeholder === "string" &&
			this.searchable
		) {
			editPlaceholder = this.displayLabel || this.value;
		}

		let readonlyValue = this.displayLabel;
		if (this.searchable && this.value?.length) {
			if (this.variant === "multiple") {
				readonlyValue = this.label || this.placeholder;
			} else if (typeof this.value === "string") {
				readonlyValue = this.displayLabel || this.value;
			}
		}

		const uncontrolledTag = this.variant === "tag" && this.uncontrolled;
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const triggeredByKeyboard =
			this.eventTrigger && this.eventTrigger !== "mouse";
		const shouldHideClearButtonForKeyboardSearch =
			this.searchable && this.editable && triggeredByKeyboard;
		const lineStyle = this.getLineStyle();

		// should keep the search string on display while pressing arrow down on the options
		if (this.searchable && triggeredByKeyboard) {
			const displayInputValue =
				this.displayInput &&
				this.displayInput instanceof HTMLInputElement &&
				this.displayInput.value;
			if (displayInputValue) {
				readonlyValue = displayInputValue;
			}
		}

		return (
			<FormControl
				inputId={this.inputId}
				label={this.label}
				labelId={this.labelId}
				hasLabelSlot={this.hasLabelSlot}
				hasLabelInfoSlot={this.hasLabelInfoSlot}
				helpTextId={this.helpTextId}
				helpText={this.helpText}
				hasHelpTextSlot={this.hasHelpTextSlot}
				hasFrontSlot={this.hasFrontSlot}
				hasRearSlot={this.hasRearSlot}
				size={this.size}
				onLabelClick={this.handleLabelClick}
				hasValue={this.value?.length > 0}
				isDisabled={this.disabled}
				isRequired={this.required}
				hasError={this.error}
				cssClasses={this.cssClasses}
				source={"select"}
				tooltip={this.tooltip}
				tooltipId={this.tooltip ? `${this.inputId}-tooltip` : undefined}
			>
				<div
					part="combobox"
					class={`select__combobox${this.truncate ? " truncate" : ""}${
						lineStyle ? " select__combobox--tag-lines" : ""
					}`}
					onKeyDown={this.handleComboboxKeyDown}
					onMouseDown={this.handleComboboxMouseDown}
					ref={this.setLocalComboboxRef}
					style={lineStyle}
					data-testid="combobox"
				>
					{this.showPrefix && (
						<span part="prefix" class="select__prefix">
							<slot name="prefix" />
						</span>
					)}

					{this.variant === "multiple" && this.value.length ? (
						this.searchable ? (
							<span class="select__multiple">
								<span
									part="counter"
									class={{
										select__count: true,
										"select__count--custom": this.hasCounterSlot,
									}}
								>
									{!this.hasCounterSlot ? ( // show number tag without tooltip as default
										this.value.length
									) : (
										<slot name="counter" />
									)}
								</span>
								{/** To displaying a tooltip, we let users add number tag too */}
								<slot name="counter-label" />
							</span>
						) : !this.hasCounterSlot ? ( // show number tag without tooltip as default
							<span class="select__multiple">
								<span part="counter" class="select__count">
									{this.value.length}
								</span>
								{!this.searchable ? this.label || this.placeholder : ""}
							</span> // To displaying a tooltip, we let users add number tag too
						) : (
							<span class={"select__multiple"}>
								<span
									part="counter"
									class="select__count select__count--custom"
								>
									<slot name="counter" />
								</span>
								<slot name="counter-label" />
							</span>
						)
					) : (
						""
					)}

					{!uncontrolledTag &&
						(!this.editable
							? this.readonlyInputElement(readonlyValue, describedId, prop)
							: this.searchInputElement(editPlaceholder, describedId, prop))}

					{this.variant === "tag"
						? this.selectedTagsInDisplay(tagRemove, {
								editPlaceholder,
								describedId,
								prop,
						  })
						: ""}

					{((this.autocomplete && this.value) ||
						!shouldHideClearButtonForKeyboardSearch) &&
					this.hasClearIcon /** do not show clear button while searching */ ? (
						<button
							part="clear-button"
							class="select__clear"
							type="button"
							aria-label={this.i18n?.clearEntry || this.defaultI18n.clearEntry}
							onMouseDown={this.handleClearMouseDown}
							onClick={this.handleClearClick}
							data-testid="clear-button"
						>
							<slot name="clear-icon">
								<hbr-icon
									asset={customSystemIcons?.["x-circle"] || xCircle}
									size={this.size === "small" ? "14px" : "16px"}
								/>
							</slot>
						</button>
					) : (
						""
					)}

					<span part="expand-icon" class="select__expand-icon">
						<slot name="expand-icon">
							<hbr-icon
								class={
									this.open
										? "select__icon select__icon__flipped"
										: "select__icon"
								}
								asset={customSystemIcons?.["caret-down"] || caretDown}
							/>
						</slot>
					</span>
				</div>
			</FormControl>
		);
	}
}
