import {
	Component,
	Element,
	Event,
	EventEmitter,
	Fragment,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { check } from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

/**
 * @since 2.0
 * @status stable
 *
 * @slot - The option's label. Make sure to use only string text. No other elements are allowed. If you need to use other elements, use the prefix or suffix slot.
 * @slot prefix - An optional prefix, usually an icon or icon button.
 * @slot suffix - An optional suffix, usually an icon or icon button.
 *
 * @part base - The component's base wrapper.
 * @part label - The option's label.
 * @part prefix - The container that wraps the prefix.
 * @part suffix - The container that wraps the suffix.
 * @part checked-icon - The container that wraps the selected icon. 'noCheckMark' prop should be set to false to show the icon.
 * @part wrapper - The container that wraps the option. For admin sentiment only.
 *
 * @csspart base - The component's base wrapper.
 * @csspart label - The option's label.
 * @csspart prefix - The container that wraps the prefix.
 * @csspart suffix - The container that wraps the suffix.
 */

@Component({
	tag: "hbr-option",
	styleUrl: "option.scss",
	shadow: true,
})
export class HbrOption {
	private cachedTextLabel: string;
	@Element() host: HTMLHbrOptionElement;

	@State() hovered = false; // we need this because Safari doesn't honor :hover styles while dragging
	@State() current = false; // the user has keyed into the option, but hasn't selected it yet (shows a highlight)
	@State() singleNonBreakableWord = false;

	/** value prop for storing value */
	@Prop({ reflect: true }) value;
	/** Set to true to draw the menu item in a disabled state. */
	@Prop({ reflect: true }) disabled = false;

	/** The Option's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** The Option's sentiment. */
	@Prop({ mutable: true, reflect: true }) sentiment;

	/** selected prop for select component to add */
	@Prop({ reflect: true, mutable: true }) selected = false; // the option is selected and has aria-selected="true"

	/** Set to true to hide the check mark. */
	@Prop({ mutable: true }) noCheckMark = false;

	/** Set to true to indicate a custom option. */
	@Prop({ mutable: true, reflect: true }) custom: boolean;

	/** Set to true to allow spaces in the option's value. */
	@Prop({ reflect: true }) allowSpace: boolean;

	/** Truncates the label if it is longer than 3 lines, showing only 3 lines with truncation. */
	@Prop() truncate: boolean;

	/** The displayed label when an option is selected. since v2.9.18 */
	@Prop() display: string;

	/** Emitted when the option is clicked. */
	@Event({ eventName: "hbr-option-click" }) hbrChange: EventEmitter;

	@Watch("value")
	handleValueChange() {
		// Ensure the value is a string. This ensures the next line doesn't error and allows framework users to pass numbers
		// instead of requiring them to cast the value to a string.
		if (typeof this.value !== "string") {
			this.value = String(this.value);
		}
		setTimeout(() => {
			if (
				this.value.includes(" ") &&
				!this.allowSpace &&
				!this.host.hasAttribute("allow-space")
			) {
				console.error(
					"Option values cannot include a space. All spaces have been replaced with underscores.",
					this,
				);
				this.value = this.value.replace(/ /g, "_");
			}
		});
	}

	private handleMouseEnter = () => {
		this.hovered = true;
	};

	private handleMouseLeave = () => {
		this.hovered = false;
	};

	private isSingleNonBreakableWord(label: string) {
		const text = label.trim();

		return text.length > 0 && !/[\s\u002d\u2010-\u2015]/.test(text);
	}

	handleDefaultSlotChange = async () => {
		if (this.custom) {
			// Backward-compat: previously consumers wrapped custom option content in `"..."`.
			// Quotes are now added via CSS pseudo-elements outside the ellipsis container, so strip any
			// user-supplied wrapping quotes to avoid `""foo""` and ensure the closing quote stays visible after truncation.
			this.stripWrappingQuotes();
		}

		const textLabel = await this.getTextLabel();
		this.singleNonBreakableWord = this.isSingleNonBreakableWord(
			textLabel ?? "",
		);

		// Ignore the first time the label is set
		if (typeof this.cachedTextLabel === "undefined") {
			this.cachedTextLabel = textLabel;
			return;
		}
		// When the label changes, emit a slotchange event so parent controls see it
		if (textLabel !== this.cachedTextLabel) {
			this.cachedTextLabel = textLabel;
		}
	};

	private stripWrappingQuotes() {
		const slot = this.host?.shadowRoot?.querySelector(
			"slot:not([name])",
		) as HTMLSlotElement | null;
		if (!slot) return;

		const textNodes: Text[] = [];
		for (const node of slot.assignedNodes({ flatten: true })) {
			if (node.nodeType === Node.TEXT_NODE) {
				if ((node.textContent ?? "").trim()) textNodes.push(node as Text);
			} else if (node.nodeType === Node.ELEMENT_NODE) {
				const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
				let current = walker.nextNode() as Text | null;
				while (current) {
					if ((current.textContent ?? "").trim()) textNodes.push(current);
					current = walker.nextNode() as Text | null;
				}
			}
		}

		if (!textNodes.length) return;

		const first = textNodes[0];
		const last = textNodes[textNodes.length - 1];
		const firstText = first.textContent ?? "";
		const lastText = last.textContent ?? "";

		if (!/^\s*"/.test(firstText) || !/"\s*$/.test(lastText)) {
			return;
		}

		if (first === last) {
			first.textContent = firstText
				.replace(/^(\s*)"/, "$1")
				.replace(/"(\s*)$/, "$1");
			return;
		}

		first.textContent = firstText.replace(/^(\s*)"/, "$1");
		last.textContent = lastText.replace(/"(\s*)$/, "$1");
	}

	componentDidRender() {
		const checkbox = this.host.querySelector("hbr-checkbox");

		if (checkbox) {
			if (this.disabled) {
				checkbox.disabled = true;
			}
			if (this.selected) {
				checkbox.checked = true;
			} else {
				if (!checkbox.checked) {
					//for uncontrolled checkbox - checked on implementation
					checkbox.checked = false;
				}
			}
		}
	}

	connectedCallback() {
		const checkbox = this.host.querySelector("hbr-checkbox");
		if (checkbox) this.noCheckMark = true;
	}

	/** Returns a plain text label based on the option's content. */
	@Method()
	async getTextLabel() {
		/** Make sure take text content only from the default slot. Not from the prefix or suffix slot  */
		const slot = this.host?.shadowRoot?.querySelector(
			"slot:not([name])",
		) as HTMLSlotElement;

		if (!slot) {
			return;
		}

		let textContent = "";
		const assignedNodes = slot.assignedNodes({ flatten: true });
		assignedNodes.forEach((node) => {
			if (node.nodeType === Node.TEXT_NODE) {
				textContent += node.textContent;
			} else if (node.nodeType === Node.ELEMENT_NODE) {
				textContent += node.textContent;
			}
		});

		return textContent.trim();
	}

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const { sentiment } = this;
		const cls = {
			option: true,
			"option--current": this.current,
			"option--disabled": this.disabled,
			"option--selected": this.selected,
			"option--small": this.size === "small",
			"option--medium": this.size === "medium",
			"option--large": this.size === "large",
			"option--custom": this.custom,
			"option--no-checkMark": this.noCheckMark,
			"option--truncate": this.truncate,
			"option--single-non-breakable-word": this.singleNonBreakableWord,
		};
		if (sentiment) {
			cls[`option--${sentiment}`] = true;
		} else if (this.hovered) {
			cls["option--hover"] = true;
		}

		const optionChildren = (
			<Fragment>
				<div part="prefix" class="option__prefix">
					<slot name="prefix" />
				</div>
				{this.custom ? (
					<div part="label" class="option__label option__label--custom">
						<span class="option__custom-label">
							<slot onSlotchange={this.handleDefaultSlotChange} />
						</span>
					</div>
				) : (
					<div part="label" class="option__label">
						<slot onSlotchange={this.handleDefaultSlotChange} />
					</div>
				)}
				<div part="suffix" class="option__suffix">
					<slot name="suffix" />
				</div>
				{!this.noCheckMark && (
					<hbr-icon
						part="checked-icon"
						class="option__check"
						asset={customSystemIcons?.check || check}
					/>
				)}
			</Fragment>
		);

		return (
			<Host
				aria-disabled={this.disabled}
				role="option"
				aria-selected={this.selected ? "true" : null}
				onClick={(event: MouseEvent) => {
					if (this.disabled) {
						event.preventDefault();
						event.stopPropagation();
						return;
					}
					if (!this.host.isConnected) {
						return;
					}
					this.hbrChange.emit({
						value: this.value,
						custom: this.custom,
					});
				}}
			>
				<div
					onMouseEnter={this.handleMouseEnter}
					onMouseLeave={this.handleMouseLeave}
					class={cls}
					part="base"
				>
					{sentiment && sentiment === "admin" ? (
						<div class="option__wrapper" part="wrapper">
							{optionChildren}
						</div>
					) : (
						optionChildren
					)}
				</div>
			</Host>
		);
	}
}
